import java.time.ZonedDateTime
import java.time.format.TextStyle
import java.util.Locale

enum class Destination { Home, Round, Topic, Connect, Reliability, Entry, Settings }

data class ThoughtRow(
    val id: String,
    val text: String,
    val state: ThoughtState,
    val identifier: String?,
    val createdAt: Long,
)

/** Everything the home screen shows. Built from the database and settings. */
data class HomeUi(
    val bearName: String = "Bear",
    val greeting: String = "Guten Abend.",
    val dateLabel: String = "",
    val hint: String? = null,
    val status: String? = null,
    val statusAction: String? = null,
    val statusTarget: Destination? = null,
    val latest: ThoughtRow? = null,
    val connected: Boolean = false,
    /** Topics and thoughts in the list of entries. */
    val entryCount: Int = 0,
    val waitingTitles: List<String> = emptyList(),
    val stuckId: String? = null,
    val stuckTitle: String? = null,
    val sleeping: Boolean = false,
)

/** One card in the list of entries: title and next step, and a short line above. */
data class EntryCard(
    val id: String,
    val meta: String,
    val title: String,
    val step: String?,
    /** Waiting in a round or left lying: the card asks for attention. */
    val highlight: Boolean = false,
)

data class EntriesUi(
    val topics: List<EntryCard> = emptyList(),
    val thoughts: List<EntryCard> = emptyList(),
) {
    val count: Int get() = topics.size + thoughts.size

    val summary: String get() = listOfNotNull(
        topics.size.takeIf { it > 0 }?.let { if (it == 1) "1 Thema" else "$it Themen" },
        thoughts.size.takeIf { it > 0 }?.let { if (it == 1) "1 Gedanke" else "$it Gedanken" },
    ).joinToString(" · ")
}

/**
 * Topics and thoughts in the order of „Deine Einträge“: waiting and stuck topics first,
 * then by due day, then the thoughts that are not topics. The widgets use the same order.
 */
fun entriesInOrder(topics: List<TopicEntity>, thoughts: List<ThoughtEntity>): Pair<List<TopicEntity>, List<ThoughtEntity>> {
    val topicIds = topics.map { it.issueId }.toSet()
    val order = compareBy<TopicEntity>({ !it.inRound && !it.stuck }, { it.status != TopicStatus.Active }, { it.nextDueEpochDay })
    return topics.sortedWith(order) to thoughts.filter { it.id !in topicIds }
}

/** The entry view: a topic, or a captured thought that is not a topic yet. */
data class EntryUi(
    val id: String,
    val isTopic: Boolean,
    val meta: String,
    val title: String,
    val sentences: List<String> = emptyList(),
    val step: String = "",
    val choice: RhythmChoice = RhythmChoice.Normal,
    /** „Nächste Runde: morgen“, „Kommt in keiner Runde“ and so on. */
    val next: String? = null,
    /** The rest of a thought, or the Linear description without the Bear block. Read only. */
    val body: String? = null,
    val url: String? = null,
    /** Where the last change is: on the phone, on its way, or a problem. */
    val sync: String? = null,
    val syncProblem: Boolean = false,
    val stuck: Boolean = false,
    val waiting: Boolean = false,
    val paused: Boolean = false,
)

/** What is being edited in the entry view. Compared with the entry to know if there is something to save. */
data class EntryDraft(
    val id: String,
    val isTopic: Boolean,
    val title: String,
    val sentences: List<String>,
    val step: String,
    val choice: RhythmChoice,
)

fun EntryUi.toDraft() = EntryDraft(id, isTopic, title, sentences, step, choice)

/** Everything the round card shows. */
data class RoundUi(
    val issueId: String,
    /** „1 von 3“ when a round brings several topics. */
    val position: String?,
    val title: String,
    val meta: String,
    val sentence: String?,
    val step: String?,
    val next: Map<Feedback, String>,
    val showHint: Boolean,
)

/** The round screen waits for the database before it decides there is nothing to show. */
sealed interface RoundState {
    data object Loading : RoundState
    data object None : RoundState
    data class Show(val ui: RoundUi) : RoundState
}

data class RoundInput(
    val typed: String = "",
    val confirmed: Boolean = false,
    val feedback: Feedback = Feedback.Passt,
    val editingStep: Boolean = false,
    val stepDraft: String = "",
)

object Words {
    private val de = Locale.GERMAN

    fun greeting(now: ZonedDateTime = ZonedDateTime.now()): String = when (now.hour) {
        in 5..10 -> "Guten Morgen."
        in 11..16 -> "Guten Tag."
        in 17..22 -> "Guten Abend."
        else -> "Gute Nacht."
    }

    fun dateLabel(now: ZonedDateTime = ZonedDateTime.now()): String =
        now.dayOfWeek.getDisplayName(TextStyle.FULL, de) + ", " + now.dayOfMonth + ". " + now.month.getDisplayName(TextStyle.FULL, de)

    fun thoughtState(row: ThoughtRow): String = when (row.state) {
        ThoughtState.Local -> "Liegt sicher bei mir"
        ThoughtState.Sending -> "Liegt sicher bei mir · wird übertragen"
        ThoughtState.InLinear -> "In Linear als ${row.identifier}"
        ThoughtState.NeedsAttention -> "Liegt sicher bei mir · Linear braucht dich"
    }

    /** Fuzzy on purpose: rounds are irregular. „heute Abend“, „morgen Abend“, „Donnerstagabend“. */
    fun nextRound(at: Long, now: ZonedDateTime = ZonedDateTime.now()): String {
        val t = Instant.ofEpochMilli(at).atZone(now.zone)
        val part = when (t.hour) {
            in 5..10 -> "morgen" to "früh"
            in 11..16 -> "mittag" to "mittag"
            else -> "abend" to "abend"
        }
        val days = java.time.temporal.ChronoUnit.DAYS.between(now.toLocalDate(), t.toLocalDate())
        return when (days) {
            0L -> if (part.first == "morgen") "heute früh" else "heute ${part.first.replaceFirstChar { it.uppercase() }}"
            1L -> if (part.first == "morgen") "morgen früh" else "morgen ${part.first.replaceFirstChar { it.uppercase() }}"
            else -> t.dayOfWeek.getDisplayName(TextStyle.FULL, de) + part.second
        }
    }

    /** „heute zwischen 19 und 21 Uhr“, „Donnerstag zwischen 8 und 9:30 Uhr“: the window, not the minute. */
    fun nextRoundBetween(at: Long, windows: List<RoundWindow>, now: ZonedDateTime = ZonedDateTime.now()): String {
        val t = Instant.ofEpochMilli(at).atZone(now.zone)
        val day = when (java.time.temporal.ChronoUnit.DAYS.between(now.toLocalDate(), t.toLocalDate())) {
            0L -> "heute"
            1L -> "morgen"
            else -> t.dayOfWeek.getDisplayName(TextStyle.FULL, de)
        }
        val window = RoundPlanner.windowOf(t.toInstant(), now.zone, windows)
        return if (window != null) "$day ${window.between()}" else "$day um %d:%02d Uhr".format(t.hour, t.minute)
    }

    /** „heute“, „morgen“, „in 4 Tagen“: when a topic is due. */
    fun dueIn(epochDay: Long, today: LocalDate = LocalDate.now()): String = when (val days = epochDay - today.toEpochDay()) {
        in Long.MIN_VALUE..0L -> "heute"
        1L -> "morgen"
        else -> "in $days Tagen"
    }

    fun time(at: Long, zone: ZoneId = ZoneId.systemDefault()): String {
        val t = Instant.ofEpochMilli(at).atZone(zone)
        val day = t.dayOfWeek.getDisplayName(TextStyle.SHORT, de).removeSuffix(".")
        return "%s %02d:%02d".format(day, t.hour, t.minute)
    }
}

package app.kiumu.bear.data.settings

import android.content.Context
import android.security.keystore.KeyGenParameterSpec
import android.security.keystore.KeyProperties
import android.util.Base64
