private val Context.store by preferencesDataStore(name = "bear")

/** Small settings. The Linear key is stored encrypted with a Keystore key. */
data class BearSettings(
    val connectedAs: String? = null,
    val hasApiKey: Boolean = false,
    /** The bear's name. The app itself stays „Bear“ on the home screen. */
    val bearName: String = BearName.DEFAULT,
    val windows: List<RoundWindow> = listOf(RoundWindow.Evening),
    val nextRoundAt: Long? = null,
    val lastSyncAt: Long? = null,
    val hintsSeen: Set<String> = emptySet(),
    val onboarding: OnboardingState = OnboardingState(),
)

object BearName {
    const val DEFAULT = "Bear"
    const val MAX_LENGTH = 20

    /** Trimmed, single spaces, not too long. Null if nothing is left. */
    fun clean(input: String): String? =
        input.trim().replace(Regex("\\s+"), " ").take(MAX_LENGTH).trim().ifEmpty { null }
}

/**
 * Where the first-run guide stands. [step] is the name of an onboarding step; it is
 * saved after every step, so an interruption loses nothing. [nameOnly] is set for an
 * install that was in use before the guide existed: it only asks for the name.
 */
data class OnboardingState(
    val started: Boolean = false,
    val done: Boolean = false,
    val step: String? = null,
    val nameOnly: Boolean = false,
    /** The thought captured during the guide, and the topic chosen in it. */
    val thoughtId: String? = null,
    val topicId: String? = null,
)

object Hints {
    const val CAPTURE = "capture"
    const val SAVED = "saved"
    const val ROUND = "round"
}

class SettingsStore(private val context: Context) {
    private object K {
        val apiKey = stringPreferencesKey("api_key_enc")
        val connectedAs = stringPreferencesKey("connected_as")
        val inboxTeamId = stringPreferencesKey("inbox_team_id")
        val triageStateId = stringPreferencesKey("triage_state_id")
        val bearName = stringPreferencesKey("bear_name")
        val windows = stringPreferencesKey("round_windows")
        // Slice 1 and 2 had one window. Read once if there is no list yet.
        val windowStart = intPreferencesKey("window_start_min")
        val windowEnd = intPreferencesKey("window_end_min")
        val onboardingStarted = booleanPreferencesKey("onboarding_started")
        val onboardingDone = booleanPreferencesKey("onboarding_done")
        val onboardingStep = stringPreferencesKey("onboarding_step")
        val onboardingNameOnly = booleanPreferencesKey("onboarding_name_only")
        val onboardingThought = stringPreferencesKey("onboarding_thought")
        val onboardingTopic = stringPreferencesKey("onboarding_topic")
        val nextRoundAt = longPreferencesKey("next_round_at")
        val lastSyncAt = longPreferencesKey("last_sync_at")
        val hints = stringSetPreferencesKey("hints_seen")
    }

    val settings: Flow<BearSettings> = context.store.data.map { it.toSettings() }

    suspend fun current(): BearSettings = settings.first()

    private fun Preferences.toSettings() = BearSettings(
        connectedAs = this[K.connectedAs],
        hasApiKey = this[K.apiKey] != null,
        bearName = this[K.bearName] ?: BearName.DEFAULT,
        windows = this[K.windows]?.let { RoundWindow.parseList(it) } ?: listOf(legacyWindow()),
        nextRoundAt = this[K.nextRoundAt],
        lastSyncAt = this[K.lastSyncAt],
        hintsSeen = this[K.hints] ?: emptySet(),
        onboarding = OnboardingState(
            started = this[K.onboardingStarted] == true,
            done = this[K.onboardingDone] == true,
            step = this[K.onboardingStep],
            nameOnly = this[K.onboardingNameOnly] == true,
            thoughtId = this[K.onboardingThought],
            topicId = this[K.onboardingTopic],
        ),
    )

    private fun Preferences.legacyWindow(): RoundWindow = runCatching {
        RoundWindow(
            LocalTime.ofSecondOfDay((this[K.windowStart] ?: (19 * 60)) * 60L),
            LocalTime.ofSecondOfDay((this[K.windowEnd] ?: (21 * 60)) * 60L),
        )
    }.getOrDefault(RoundWindow.Evening)

    suspend fun apiKey(): String? = context.store.data.first()[K.apiKey]?.let { KeystoreCipher.decrypt(it) }

    suspend fun saveConnection(apiKey: String, name: String) = context.store.edit {
        it[K.apiKey] = KeystoreCipher.encrypt(apiKey)
        it[K.connectedAs] = name
    }

    suspend fun inbox(): Pair<String, String>? {
        val p = context.store.data.first()
        val team = p[K.inboxTeamId] ?: return null
        val state = p[K.triageStateId] ?: return null
        return team to state
    }

    suspend fun saveInbox(teamId: String, triageStateId: String) = context.store.edit {
        it[K.inboxTeamId] = teamId
        it[K.triageStateId] = triageStateId
    }

    suspend fun setNextRoundAt(at: Long?) = context.store.edit {
        if (at == null) it.remove(K.nextRoundAt) else it[K.nextRoundAt] = at
    }

    suspend fun markSynced(at: Long) = context.store.edit { it[K.lastSyncAt] = at }

    suspend fun markHint(vararg hints: String) = context.store.edit {
        it[K.hints] = (it[K.hints] ?: emptySet()) + hints
    }

    suspend fun setBearName(name: String) = context.store.edit { it[K.bearName] = name }

    suspend fun setWindows(windows: List<RoundWindow>) = context.store.edit { it[K.windows] = RoundWindow.formatList(windows) }

    /** Starts the guide once. An install that was already in use only gets the name step. */
    suspend fun startOnboarding(nameOnly: Boolean) = context.store.edit {
        if (it[K.onboardingStarted] == true) return@edit
        it[K.onboardingStarted] = true
        it[K.onboardingNameOnly] = nameOnly
    }

    suspend fun setOnboardingStep(step: String) = context.store.edit { it[K.onboardingStep] = step }

    suspend fun setOnboardingThought(id: String?) = context.store.edit {
        if (id == null) it.remove(K.onboardingThought) else it[K.onboardingThought] = id
    }

    suspend fun setOnboardingTopic(id: String?) = context.store.edit {
        if (id == null) it.remove(K.onboardingTopic) else it[K.onboardingTopic] = id
    }

    suspend fun finishOnboarding() = context.store.edit { it[K.onboardingDone] = true }

    /**
     * Debug builds only: the guide starts again on the next launch. Data stays. With
     * [full] it runs all steps even on an install that is in use.
     */
    suspend fun resetOnboarding(full: Boolean = false) = context.store.edit {
        it.remove(K.onboardingStarted)
        it.remove(K.onboardingDone)
        it.remove(K.onboardingStep)
        it.remove(K.onboardingNameOnly)
        it.remove(K.onboardingThought)
        it.remove(K.onboardingTopic)
        if (full) {
            it[K.onboardingStarted] = true
            it[K.onboardingNameOnly] = false
        }
    }
}

/** AES-GCM with a key that never leaves the Android Keystore. */
object KeystoreCipher {
    private const val ALIAS = "bear_linear_key"

    private fun key(): SecretKey {
        val ks = KeyStore.getInstance("AndroidKeyStore").apply { load(null) }
        (ks.getEntry(ALIAS, null) as? KeyStore.SecretKeyEntry)?.let { return it.secretKey }
        val gen = KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore")
        gen.init(
            KeyGenParameterSpec.Builder(ALIAS, KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT)
                .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
                .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
                .build(),
        )
        return gen.generateKey()
    }

    fun encrypt(plain: String): String {
        val c = Cipher.getInstance("AES/GCM/NoPadding").apply { init(Cipher.ENCRYPT_MODE, key()) }
        val out = c.iv + c.doFinal(plain.toByteArray())
        return Base64.encodeToString(out, Base64.NO_WRAP)
    }

    fun decrypt(stored: String): String? = runCatching {
        val bytes = Base64.decode(stored, Base64.NO_WRAP)
        val c = Cipher.getInstance("AES/GCM/NoPadding")
        c.init(Cipher.DECRYPT_MODE, key(), GCMParameterSpec(128, bytes, 0, 12))
        String(c.doFinal(bytes, 12, bytes.size - 12))
    }.getOrNull()
}

package app.kiumu.bear.domain

import java.text.Normalizer

/**
 * Tolerant comparison for typing a sentence. Case, spacing, punctuation, quote and
 * dash variants do not count. Beyond that, roughly one typo per 20 characters is
 * allowed (Palin et al. 2019: phones average 2.3 % uncorrected errors).
 */
object SentenceMatcher {

    fun normalize(text: String): String {
        val nfkc = Normalizer.normalize(text, Normalizer.Form.NFKC).lowercase()
        val sb = StringBuilder()
        var lastSpace = true
        for (ch in nfkc) {
            val c = when (ch) {
                '„', '“', '”', '‚', '‘', '’', '«', '»', '"', '\'' -> null
                '–', '—', '‐', '‑', '−' -> '-'
                else -> ch
            } ?: continue
            if (c.isLetterOrDigit()) {
                sb.append(c); lastSpace = false
            } else if (!lastSpace) {
                sb.append(' '); lastSpace = true
            }
        }
        return sb.toString().trim()
    }

    fun tolerance(target: String): Int {
        val n = normalize(target).length
        return if (n < 12) 0 else maxOf(1, n / 20)
    }

    /** True when the typed text matches the whole sentence within tolerance. */
    fun matches(typed: String, target: String): Boolean {
        val a = normalize(typed)
        val b = normalize(target)
        if (a.isEmpty()) return false
        return levenshtein(a, b) <= tolerance(target)
    }

    /**
     * Progress from 0 to 1 while typing. It only advances while the typed text is
     * still close to the beginning of the sentence, so a wrong turn is visible.
     */
    fun progress(typed: String, target: String): Progress {
        val a = normalize(typed)
        val b = normalize(target)
        if (a.isEmpty() || b.isEmpty()) return Progress(0f, onTrack = true)
        val prefix = b.take(a.length)
        val onTrack = levenshtein(a, prefix) <= maxOf(1, tolerance(target))
        val value = (minOf(a.length, b.length).toFloat() / b.length).coerceIn(0f, 1f)
        return Progress(if (onTrack) value else value * 0.6f, onTrack)
    }

    data class Progress(val value: Float, val onTrack: Boolean)

    internal fun levenshtein(a: String, b: String): Int {
        if (a == b) return 0
        if (a.isEmpty()) return b.length
        if (b.isEmpty()) return a.length
        var prev = IntArray(b.length + 1) { it }
        var cur = IntArray(b.length + 1)
        for (i in 1..a.length) {
            cur[0] = i
            for (j in 1..b.length) {
                val cost = if (a[i - 1] == b[j - 1]) 0 else 1
                cur[j] = minOf(cur[j - 1] + 1, prev[j] + 1, prev[j - 1] + cost)
            }
            val t = prev; prev = cur; cur = t
        }
        return prev[b.length]
    }
}

package app.kiumu.bear.data.db

import android.content.Context
import androidx.room.AutoMigration
import androidx.room.ColumnInfo
import androidx.room.Dao
import androidx.room.Database
import androidx.room.Entity
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.PrimaryKey
import androidx.room.Query
import androidx.room.Room
import androidx.room.RoomDatabase
import androidx.room.Upsert
import app.kiumu.bear.domain.RoundSelection
import kotlinx.coroutines.flow.Flow

enum class ThoughtState { Local, Sending, InLinear, NeedsAttention }

/** A captured thought. It is saved here first; Linear comes second. */
@Entity(tableName = "thoughts")
data class ThoughtEntity(
    @PrimaryKey val id: String,
    val text: String,
    val createdAt: Long,
    val state: ThoughtState,
    val identifier: String? = null,
    val lastError: String? = null,
)

enum class TopicStatus { Active, Remembered, Paused, Ended }

/** A topic Bear brings in rounds. The Linear issue stays the source of truth. */
@Entity(tableName = "topics")
data class TopicEntity(
    @PrimaryKey val issueId: String,
    val identifier: String,
    val title: String,
    val url: String,
    val sentences: List<String>,
    val step: String?,
    val intervalFrom: Int?,
    val intervalTo: Int?,
    val rhythm: String,
    val intervalFactor: Double,
    val nextDueEpochDay: Long,
    val inRound: Boolean,
    val unhandledRounds: Int,
    val sentenceIndex: Int,
    val sentenceUses: Int,
    val linearStateType: String,
    val status: TopicStatus,
    val lastSyncedAt: Long,
    /** The Linear description as last read, shown read-only. Null until the first read. */
    @ColumnInfo(defaultValue = "NULL") val description: String? = null,
) {
    /** Three rounds in a row without an answer: Bear stops bringing it and asks once. */
    val stuck: Boolean get() = !inRound && unhandledRounds >= RoundSelection.STUCK_AFTER
}

/**
 * Changes made in Bear that still have to reach Linear. One row per issue; later
 * changes merge into it. The row is removed once Linear has all of it.
 */
@Entity(tableName = "edits")
data class EditEntity(
    @PrimaryKey val issueId: String,
    /** New title, or null if the title did not change. */
    val title: String? = null,
    /** Sentences or step changed; the Bear block is written from the topic. */
    val block: Boolean = false,
    /** New rhythm label, e.g. „normal“ or „nur merken“, or null. */
    val rhythmLabel: String? = null,
    val version: Int = 1,
    val lastError: String? = null,
    val updatedAt: Long,
)

enum class RoundKind { Regular, Probe }

/** One planned round: when it should have come and when it actually did. */
@Entity(tableName = "round_log")
data class RoundLogEntity(
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    val kind: RoundKind,
    val plannedAt: Long,
    val firedAt: Long? = null,
    val shownAt: Long? = null,
    val note: String? = null,
)

@Dao
interface ThoughtDao {
    @Query("SELECT * FROM thoughts ORDER BY createdAt DESC")
    fun observeAll(): Flow<List<ThoughtEntity>>

    @Query("SELECT * FROM thoughts WHERE id = :id")
    suspend fun get(id: String): ThoughtEntity?

    @Query("SELECT * FROM thoughts WHERE id = :id")
    fun observe(id: String): Flow<ThoughtEntity?>

    @Query("SELECT COUNT(*) FROM thoughts")
    suspend fun count(): Int

    @Query("SELECT * FROM thoughts WHERE state != 'InLinear'")
    suspend fun pending(): List<ThoughtEntity>

    @Insert(onConflict = OnConflictStrategy.ABORT)
    suspend fun insert(thought: ThoughtEntity)

    @Upsert
    suspend fun upsert(thought: ThoughtEntity)
}

@Dao
interface TopicDao {
    /** All topics that are not ended, the ones due soonest first. */
    @Query("SELECT * FROM topics WHERE status != 'Ended' ORDER BY nextDueEpochDay, title")
    fun observeAll(): Flow<List<TopicEntity>>

    @Query("SELECT * FROM topics WHERE status != 'Ended'")
    suspend fun open(): List<TopicEntity>

    @Query("SELECT * FROM topics WHERE status = 'Active'")
    suspend fun active(): List<TopicEntity>

    @Query("SELECT * FROM topics WHERE inRound = 1 AND status = 'Active'")
    suspend fun inRound(): List<TopicEntity>

    @Query("SELECT * FROM topics WHERE issueId = :issueId")
    suspend fun get(issueId: String): TopicEntity?

    @Query("SELECT * FROM topics WHERE issueId = :issueId")
    fun observe(issueId: String): Flow<TopicEntity?>

    @Upsert
    suspend fun upsert(topic: TopicEntity)

    @Query("UPDATE topics SET description = :description, lastSyncedAt = :at WHERE issueId = :issueId")
    suspend fun setDescription(issueId: String, description: String?, at: Long)
}

@Dao
interface EditDao {
    @Query("SELECT * FROM edits")
    fun observeAll(): Flow<List<EditEntity>>

    @Query("SELECT * FROM edits")
    suspend fun all(): List<EditEntity>

    @Query("SELECT * FROM edits WHERE issueId = :issueId")
    suspend fun get(issueId: String): EditEntity?

    @Upsert
    suspend fun upsert(edit: EditEntity)

    @Query("UPDATE edits SET lastError = :error WHERE issueId = :issueId")
    suspend fun setError(issueId: String, error: String?)

    /** Removes the row only if nothing new came in while it was being sent. */
    @Query("DELETE FROM edits WHERE issueId = :issueId AND version = :version")
    suspend fun done(issueId: String, version: Int): Int
}

