package app.kiumu.bear.domain

/**
 * The Bear block lives at the end of a Linear description as a fenced code block
 * with the language `bear`. One entry per line, no quotes, no indentation:
 *
 * ```bear
 * Satz: Ich will die Startzeit meines Linux-Systems verbessern.
 * Schritt: systemd-analyze blame beim nächsten Neustart ansehen
 * Abstand: 3-7 Tage
 * ```
 *
 * Linear returns the content of code blocks unchanged (see LEARNINGS.md, BOX-29),
 * so the block content can be compared byte by byte. Text outside the block is
 * normalised by Linear and is never compared byte by byte.
 *
 * Lines Bear does not understand are kept in [extra] and written back unchanged
 * after the known lines, so editing a step never loses something Steven wrote.
 */
data class BearBlock(
    val sentences: List<String> = emptyList(),
    val step: String? = null,
    val interval: IntRange? = null,
    val extra: List<String> = emptyList(),
) {
    fun render(): String = buildString {
        sentences.forEach { appendLine("Satz: $it") }
        step?.let { appendLine("Schritt: $it") }
        interval?.let { appendLine("Abstand: ${it.first}-${it.last} Tage") }
        extra.forEach { appendLine(it) }
    }.trimEnd()

    companion object {
        const val MAX_SENTENCES = 3
        private val fence = Regex("```bear[ \\t]*\\n(.*?)\\n?```", RegexOption.DOT_MATCHES_ALL)
        private val intervalValue = Regex("^(\\d+)\\s*[-–]\\s*(\\d+)\\s*Tage?$", RegexOption.IGNORE_CASE)

        /** Finds the first Bear block in a description. Returns null if there is none. */
        fun find(description: String?): Found? {
            if (description == null) return null
            val match = fence.find(description) ?: return null
            return Found(match.range, parse(match.groupValues[1]))
        }

        fun parse(content: String): Parsed {
            val sentences = mutableListOf<String>()
            var step: String? = null
            var interval: IntRange? = null
            val extra = mutableListOf<String>()
            val problems = mutableListOf<Problem>()
            content.lines().forEachIndexed { index, raw ->
                val line = raw.trim()
                if (line.isEmpty()) return@forEachIndexed
                fun keep(message: String) {
                    problems += Problem(index + 1, message)
                    extra += raw
                }
                val colon = line.indexOf(':')
                if (colon <= 0) {
                    keep("Zeile ohne „Schlüssel:“")
                    return@forEachIndexed
                }
                val key = line.substring(0, colon).trim().lowercase()
                val value = line.substring(colon + 1).trim()
                when (key) {
                    "satz" -> if (value.isNotEmpty()) sentences += value else keep("„Satz:“ ohne Text")
                    "schritt" -> step = value.ifEmpty { null }
                    "abstand" -> {
                        val m = intervalValue.find(value)
                        val a = m?.groupValues?.get(1)?.toIntOrNull()
                        val b = m?.groupValues?.get(2)?.toIntOrNull()
                        if (a != null && b != null && a in 1..b) interval = a..b
                        else keep("„Abstand:“ erwartet z. B. „3-7 Tage“")
                    }
                    else -> keep("Unbekannter Schlüssel „${line.substring(0, colon)}“")
                }
            }
            if (sentences.size > MAX_SENTENCES) {
                problems += Problem(0, "Mehr als $MAX_SENTENCES Sätze; Bear nutzt die ersten $MAX_SENTENCES")
                extra.addAll(0, sentences.drop(MAX_SENTENCES).map { "Satz: $it" })
            }
            return Parsed(BearBlock(sentences.take(MAX_SENTENCES), step, interval, extra), problems)
        }

        /** Replaces the block (or appends one) and leaves all other text untouched. */
        fun writeInto(description: String?, block: BearBlock): String {
            val fencedBlock = "```bear\n${block.render()}\n```"
            val current = description.orEmpty()
            val found = fence.find(current)
            return when {
                found != null -> current.replaceRange(found.range, fencedBlock)
                current.isBlank() -> fencedBlock
                else -> current.trimEnd() + "\n\n" + fencedBlock
            }
        }
    }

    data class Found(val range: IntRange, val parsed: Parsed)
    data class Parsed(val block: BearBlock, val problems: List<Problem>)
    data class Problem(val line: Int, val message: String)
}

package app.kiumu.bear.domain

import java.time.Instant
import java.time.LocalDate
import java.time.LocalTime
import java.time.ZoneId
import java.time.ZonedDateTime
import kotlin.math.roundToInt
import kotlin.random.Random

/** A daily window in which rounds may come. Outside of all windows Bear is quiet. */
data class RoundWindow(val start: LocalTime, val end: LocalTime) {
    init { require(start < end) { "Fenster muss innerhalb eines Tages liegen" } }

    val part: DayPart get() = DayPart.of(start)

    fun describe(): String = "${start.hhmm()}–${end.hhmm()} Uhr"

    /** „zwischen 19 und 21 Uhr“, „zwischen 8 und 9:30 Uhr“. */
    fun between(): String = "zwischen ${start.short()} und ${end.short()} Uhr"

    companion object {
        /** Provisional default from the decisions of 26 September: evenings, 19–21. */
        val Evening = RoundWindow(LocalTime.of(19, 0), LocalTime.of(21, 0))

        /** Shortest window that still leaves room for a random minute. */
        const val MIN_MINUTES = 15L
        const val MAX_WINDOWS = 3

        /** Stored as „08:00-09:30,19:00-21:00“. Broken parts are dropped; nothing left means the default. */
        fun parseList(text: String?): List<RoundWindow> {
            val list = text.orEmpty().split(',').mapNotNull { part ->
                runCatching {
                    val (a, b) = part.trim().split('-')
                    RoundWindow(LocalTime.parse(a), LocalTime.parse(b))
                }.getOrNull()
            }
            return normalize(list).ifEmpty { listOf(Evening) }
        }

        fun formatList(windows: List<RoundWindow>): String = normalize(windows).joinToString(",") { "${it.start.hhmm()}-${it.end.hhmm()}" }

        /** Sorted, one per part of the day, at most three. */
        fun normalize(windows: List<RoundWindow>): List<RoundWindow> =
            windows.sortedBy { it.start }.distinctBy { it.part }.take(MAX_WINDOWS)
    }
}

/**
 * The three parts of the day a window can lie in. Each part holds at most one window,
 * so windows never overlap and „morgens“ or „abends“ always fits.
 */
enum class DayPart(val label: String, val adverb: String, val from: LocalTime, val until: LocalTime, val preset: RoundWindow) {
    Morgens("Morgens", "morgens", LocalTime.of(5, 0), LocalTime.of(11, 0), RoundWindow(LocalTime.of(8, 0), LocalTime.of(9, 30))),
    Mittags("Mittags", "mittags", LocalTime.of(11, 0), LocalTime.of(17, 0), RoundWindow(LocalTime.of(12, 0), LocalTime.of(13, 30))),
    Abends("Abends", "abends", LocalTime.of(17, 0), LocalTime.MAX, RoundWindow.Evening);

    /** Why [window] does not fit this part, or null if it does. */
    fun problem(window: RoundWindow): String? = when {
        window.start < from || window.start >= until || window.end > until ->
            "$label heißt hier zwischen ${from.short()} und ${if (until == LocalTime.MAX) "24" else until.short()} Uhr."
        java.time.Duration.between(window.start, window.end).toMinutes() < RoundWindow.MIN_MINUTES ->
            "Ein Fenster braucht mindestens ${RoundWindow.MIN_MINUTES} Minuten."
        else -> null
    }

    companion object {
        fun of(t: LocalTime): DayPart = when {
            t < Mittags.from -> Morgens
            t < Abends.from -> Mittags
            else -> Abends
        }
    }
}

private fun LocalTime.hhmm() = "%02d:%02d".format(hour, minute)

/** „8“, „9:30“, „21“. */
private fun LocalTime.short() = if (minute == 0) "$hour" else "%d:%02d".format(hour, minute)

/** Rhythm presets in days. The numbers are provisional start values. */
enum class Rhythm(val label: String, val days: IntRange) {
    Oft("oft", 1..2),
    Normal("normal", 3..7),
    Selten("selten", 14..28);

    companion object {
        const val MAX_DAYS = 42
    }
}

/**
 * What the rhythm chips offer, and the matching child label of the Linear label group
 * „Bear“. „Nur merken“ keeps the topic in the list but brings it in no round.
 */
enum class RhythmChoice(val label: String, val linearLabel: String, val rhythm: Rhythm?) {
    Oft("Oft", "oft", Rhythm.Oft),
    Normal("Normal", "normal", Rhythm.Normal),
    Selten("Selten", "selten", Rhythm.Selten),
    Merken("Nur merken", "nur merken", null);

    companion object {
        const val LINEAR_GROUP = "Bear"

        fun fromLinearLabel(name: String): RhythmChoice? = entries.firstOrNull { it.linearLabel.equals(name.trim(), ignoreCase = true) }
    }
}

enum class Feedback { Oefter, Passt, Seltener }

object RoundPlanner {

    /** How the interval factor reacts to the chips. Provisional start values. */
    fun adjustFactor(factor: Double, feedback: Feedback, confirmedWithSentence: Boolean): Double = when (feedback) {
        Feedback.Seltener -> factor * 1.5
        Feedback.Oefter -> factor / 1.5
        Feedback.Passt -> if (confirmedWithSentence) factor + 0.10 else factor
    }.coerceIn(0.25, 6.0)

    /** The day range a topic waits for, after applying its factor and the cap. */
    fun effectiveDays(rhythm: Rhythm, factor: Double, override: IntRange? = null): IntRange {
        val base = override ?: rhythm.days
        val first = (base.first * factor).roundToInt().coerceIn(1, Rhythm.MAX_DAYS)
        val last = (base.last * factor).roundToInt().coerceIn(first, Rhythm.MAX_DAYS)
        return first..last
    }

    fun nextDueDate(today: LocalDate, days: IntRange, random: Random = Random.Default): LocalDate =
        today.plusDays(random.nextInt(days.first, days.last + 1).toLong())

    /**
     * The next moment for a round: the first window on or after [dueDate] that has
     * not yet passed, at a random minute inside that window.
     */
    fun nextRoundAt(
        now: ZonedDateTime,
        dueDate: LocalDate,
        windows: List<RoundWindow>,
        random: Random = Random.Default,
    ): ZonedDateTime {
        val zone: ZoneId = now.zone
        val sorted = windows.ifEmpty { listOf(RoundWindow.Evening) }.sortedBy { it.start }
        var day = maxOf(now.toLocalDate(), dueDate)
        while (true) {
            for (window in sorted) {
                val start = day.atTime(window.start).atZone(zone)
                val end = day.atTime(window.end).atZone(zone)
                val earliest = if (now.isAfter(start)) now.plusMinutes(2) else start
                if (earliest.isBefore(end.minusMinutes(1))) {
                    val span = java.time.Duration.between(earliest, end).toMinutes().coerceAtLeast(1)
                    return earliest.plusMinutes(random.nextLong(0, span)).withSecond(0).withNano(0)
                }
            }
            day = day.plusDays(1)
        }
    }

    /** A short human description such as „in etwa 4–8 Tagen, abends“ or „…, morgens oder abends“. */
    fun describeNext(days: IntRange, windows: List<RoundWindow>): String {
        val range = if (days.first == days.last) "${days.first}" else "${days.first}–${days.last}"
        val unit = if (days.last == 1) "Tag" else "Tagen"
        return "in etwa $range $unit, ${parts(windows)}"
    }

    /** „abends“, „morgens oder abends“, „morgens, mittags oder abends“. */
    fun parts(windows: List<RoundWindow>): String {
        val names = windows.map { it.part }.distinct().sorted().map { it.adverb }.ifEmpty { listOf(DayPart.Abends.adverb) }
        return if (names.size == 1) names.single() else names.dropLast(1).joinToString(", ") + " oder " + names.last()
    }

    fun isInsideWindow(instant: Instant, zone: ZoneId, windows: List<RoundWindow>): Boolean {
        val t = instant.atZone(zone).toLocalTime()
        return windows.any { !t.isBefore(it.start) && t.isBefore(it.end) }
    }

    /** The window a planned round falls into, for „heute zwischen 19 und 21 Uhr“. */
    fun windowOf(at: Instant, zone: ZoneId, windows: List<RoundWindow>): RoundWindow? {
        val t = at.atZone(zone).toLocalTime()
        return windows.firstOrNull { !t.isBefore(it.start) && !t.isAfter(it.end) }
    }
}

package app.kiumu.bear.ui.onboarding

/**
 * The first-run guide in ten small steps (decision 12 of 26 September, report section 12).
 * Every step saves at once; every answer has a visible effect.
 */
enum class OnboardingStep {
    Name, Capture, Linear, Topic, Sentence, Windows, Notifications, Probe, Battery, Tile;

    val number: Int get() = ordinal + 1

    companion object {
        val total: Int get() = entries.size

        fun parse(name: String?): OnboardingStep? = entries.firstOrNull { it.name == name }
    }
}

/** What decides whether a step has anything to do. */
data class OnboardingFacts(
    val connected: Boolean,
    val hasThought: Boolean,
    val hasTopic: Boolean,
    val notificationsOn: Boolean,
    val batteryUnrestricted: Boolean,
)

/** Steps without anything to do are left out, forwards and backwards. */
object OnboardingFlow {
    fun applies(step: OnboardingStep, facts: OnboardingFacts): Boolean = when (step) {
        // A topic comes from Linear or from the thought captured in step 2.
        OnboardingStep.Topic -> facts.connected || facts.hasThought
        OnboardingStep.Sentence, OnboardingStep.Probe -> facts.hasTopic
        OnboardingStep.Notifications -> !facts.notificationsOn
        OnboardingStep.Battery -> !facts.batteryUnrestricted
        else -> true
    }

    /** The next step that applies, or null when the guide is over. */
    fun next(from: OnboardingStep, facts: OnboardingFacts): OnboardingStep? =
        OnboardingStep.entries.drop(from.ordinal + 1).firstOrNull { applies(it, facts) }

    fun previous(from: OnboardingStep, facts: OnboardingFacts): OnboardingStep? =
        OnboardingStep.entries.take(from.ordinal).lastOrNull { applies(it, facts) }
}

package app.kiumu.bear.domain

import java.time.LocalDate

/** What the selection needs to know about a topic. */
data class RoundCandidate(
    val id: String,
    val inRound: Boolean,
    val unhandledRounds: Int,
    val nextDue: LocalDate,
)

/**
 * Which topics a round brings. Decided on 26 September: due topics are bundled,
 * at most three per round.
 */
object RoundSelection {
    const val MAX_PER_ROUND = 3
    const val STUCK_AFTER = 3

    /** New round state of one topic. */
    data class Update(val id: String, val inRound: Boolean, val unhandledRounds: Int)

    data class Result(val updates: List<Update>, val shown: List<String>, val newlyStuck: List<String>)

    /**
     * Topics still open from the last round come first and count one more unanswered
     * round; after [STUCK_AFTER] they are no longer shown. Then the most overdue ones.
     * A probe round does not count as unanswered, and it always brings something if
     * there is any topic at all.
     */
    fun pick(topics: List<RoundCandidate>, today: LocalDate, probe: Boolean = false, max: Int = MAX_PER_ROUND): Result {
        val waiting = topics.filter { it.inRound }
        val stuck = topics.filter { !it.inRound && it.unhandledRounds >= STUCK_AFTER }
        val fresh = topics.filter { !it.inRound && it.unhandledRounds < STUCK_AFTER && !it.nextDue.isAfter(today) }

        val updates = mutableListOf<Update>()
        val newlyStuck = mutableListOf<String>()
        val carried = mutableListOf<RoundCandidate>()
        for (t in waiting.sortedWith(order)) {
            val unhandled = if (probe) t.unhandledRounds else t.unhandledRounds + 1
            if (unhandled >= STUCK_AFTER) {
                updates += Update(t.id, inRound = false, unhandledRounds = unhandled)
                newlyStuck += t.id
            } else {
                updates += Update(t.id, inRound = true, unhandledRounds = unhandled)
                carried += t
            }
        }
        val slots = (max - carried.size).coerceAtLeast(0)
        var added = fresh.sortedWith(order).take(slots)
        if (probe && carried.isEmpty() && added.isEmpty()) {
            added = (topics - stuck.toSet()).sortedWith(order).take(1)
        }
        added.forEach { updates += Update(it.id, inRound = true, unhandledRounds = 0) }
        return Result(updates, (carried + added).map { it.id }, newlyStuck)
    }

    /** The day of the next round: tomorrow for topics still waiting, otherwise the earliest due day. */
    fun nextDueDay(topics: List<RoundCandidate>, today: LocalDate): LocalDate? =
        topics.filterNot { !it.inRound && it.unhandledRounds >= STUCK_AFTER }
            .minOfOrNull { if (it.inRound) today.plusDays(1) else maxOf(it.nextDue, today) }

    private val order = compareBy<RoundCandidate>({ it.nextDue }, { it.id })
}

