/** Title and description for a captured thought. Text is never cut silently. */
object ThoughtText {
    const val MAX_TITLE = 80

    fun split(text: String): Pair<String, String?> {
        val trimmed = text.trim()
        val firstLine = trimmed.lineSequence().first().trim()
        val title = if (firstLine.length <= MAX_TITLE) firstLine else {
            val cut = firstLine.take(MAX_TITLE).substringBeforeLast(' ').ifBlank { firstLine.take(MAX_TITLE) }
            "$cut …"
        }
        val needsDescription = trimmed != title
        return title to if (needsDescription) trimmed else null
    }
}

class ThoughtRepository(
    private val context: Context,
    private val db: BearDatabase,
    private val edits: EditQueue,
) {
    fun observe() = db.thoughts().observeAll()

    fun observe(id: String) = db.thoughts().observe(id)

    /** Saves locally first. Linear comes second, via WorkManager. */
    suspend fun capture(text: String): String {
        val id = UUID.randomUUID().toString()
        db.thoughts().insert(ThoughtEntity(id, text.trim(), System.currentTimeMillis(), ThoughtState.Local))
        enqueueSend(id)
        return id
    }

    /**
     * Replaces the first line. Before the thought reaches Linear this only changes the
     * text that will be sent; afterwards the new title also goes to the issue.
     */
    suspend fun rename(id: String, title: String) {
        val t = db.thoughts().get(id) ?: return
        val clean = title.trim().ifEmpty { return }
        val text = (listOf(clean) + t.text.trim().lines().drop(1)).joinToString("\n").trim()
        if (text == t.text) return
        db.thoughts().upsert(t.copy(text = text))
        if (t.state == ThoughtState.InLinear) edits.record(id, title = ThoughtText.split(text).first)
    }

    suspend fun resendPending() {
        db.thoughts().pending().forEach { enqueueSend(it.id) }
    }

    private fun enqueueSend(id: String) {
        val request = OneTimeWorkRequestBuilder<SendThoughtWorker>()
            .setInputData(workDataOf(SendThoughtWorker.KEY_ID to id))
            .setConstraints(Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build())
            .setExpedited(OutOfQuotaPolicy.RUN_AS_NON_EXPEDITED_WORK_REQUEST)
            .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 30, TimeUnit.SECONDS)
            .build()
        WorkManager.getInstance(context).enqueueUniqueWork("send-$id", ExistingWorkPolicy.KEEP, request)
    }
}

/**
 * Changes made in Bear that still have to reach Linear. They are saved locally first
 * and sent by [EditSyncWorker], so an edit without network or key is never lost.
 */
class EditQueue(private val context: Context, private val db: BearDatabase) {
    fun observe() = db.edits().observeAll()

    suspend fun record(issueId: String, title: String? = null, block: Boolean = false, rhythmLabel: String? = null) {
        if (title == null && !block && rhythmLabel == null) return
        val old = db.edits().get(issueId)
        db.edits().upsert(
            EditEntity(
                issueId = issueId,
                title = title ?: old?.title,
                block = block || old?.block == true,
                rhythmLabel = rhythmLabel ?: old?.rhythmLabel,
                version = (old?.version ?: 0) + 1,
                lastError = null,
                updatedAt = System.currentTimeMillis(),
            ),
        )
        enqueue(issueId)
    }

    fun enqueue(issueId: String) {
        val request = OneTimeWorkRequestBuilder<EditSyncWorker>()
            .setInputData(workDataOf(EditSyncWorker.KEY_ID to issueId))
            .setConstraints(Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build())
            .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 30, TimeUnit.SECONDS)
            .build()
        // Append: an edit that arrives while the worker is finishing still gets its own run.
        WorkManager.getInstance(context).enqueueUniqueWork("edit-$issueId", ExistingWorkPolicy.APPEND_OR_REPLACE, request)
    }

    suspend fun enqueueAll() = db.edits().all().forEach { enqueue(it.issueId) }
}

/** A loaded issue before it becomes a topic. */
data class TopicPreview(
    val issue: LinearIssue,
    val block: BearBlock,
    val problems: List<BearBlock.Problem>,
    /** Already one of Bear's topics. */
    val known: Boolean,
)

/** The four answers when a topic was left lying three times. */
enum class StuckAnswer { Seltener, Pausieren, PasstSo, NichtMehrWichtig }

class TopicRepository(
    private val db: BearDatabase,
    private val settings: SettingsStore,
    private val linear: LinearClient,
    private val edits: EditQueue,
) {
    fun observeAll() = db.topics().observeAll()

    fun observe(issueId: String) = db.topics().observe(issueId)

    suspend fun preview(identifier: String): TopicPreview? {
        val key = settings.apiKey() ?: return null
        val issue = linear.issue(key, identifier.trim().uppercase()) ?: return null
        return previewOf(issue)
    }

    suspend fun previewOf(issue: LinearIssue): TopicPreview {
        val parsed = BearBlock.find(issue.description)?.parsed ?: BearBlock.Parsed(BearBlock(), emptyList())
        val known = db.topics().get(issue.id)?.let { it.status != TopicStatus.Ended } == true
        return TopicPreview(issue, parsed.block, parsed.problems, known)
    }

    /** Up to [count] open issues that changed last and are not a topic yet. Empty without a key. */
    suspend fun recent(count: Int = 5): List<LinearIssue> {
        val key = settings.apiKey() ?: return emptyList()
        val known = db.topics().open().map { it.issueId }.toSet()
        return linear.recentIssues(key, count * 2).filter { it.id !in known }.take(count)
    }

    /**
     * Adds an issue as a topic, or updates it if Bear knows it already. Without a
     * label from the group „Bear“ it gets „normal“, so Linear shows which issues
     * Bear brings.
     */
    suspend fun adopt(preview: TopicPreview, today: LocalDate = LocalDate.now()): String {
        val i = preview.issue
        val existing = db.topics().get(i.id)
        val fromLabel = i.bearLabel?.let { RhythmChoice.fromLinearLabel(it.name) }
        var topic = (existing ?: newTopic(i.id, i.identifier, i.title, today)).copy(
            identifier = i.identifier, title = i.title, url = i.url,
            sentences = preview.block.sentences, step = preview.block.step,
            intervalFrom = preview.block.interval?.first, intervalTo = preview.block.interval?.last,
            linearStateType = i.stateType, description = i.description,
            lastSyncedAt = System.currentTimeMillis(),
        )
        if (topic.status == TopicStatus.Ended) topic = topic.copy(status = TopicStatus.Active, nextDueEpochDay = today.toEpochDay())
        if (fromLabel != null) {
            // A new topic comes in the next round, whatever its rhythm; the rhythm counts from then on.
            topic = topic.withChoice(fromLabel, today).let { if (existing == null) it.copy(nextDueEpochDay = today.toEpochDay()) else it }
        }
        db.topics().upsert(topic)
        if (fromLabel == null) edits.record(i.id, rhythmLabel = topic.choice().linearLabel)
        return i.id
    }

    /** Turns a captured thought into a topic. The issue id is the thought's own UUID. */
    suspend fun fromThought(thought: ThoughtEntity, today: LocalDate = LocalDate.now()): String {
        val existing = db.topics().get(thought.id)
        if (existing != null) {
            if (existing.status == TopicStatus.Ended) db.topics().upsert(existing.copy(status = TopicStatus.Active))
            return thought.id
        }
        val (title, description) = ThoughtText.split(thought.text)
        db.topics().upsert(
            newTopic(thought.id, thought.identifier.orEmpty(), title, today.plusDays(1)).copy(description = description),
        )
        edits.record(thought.id, rhythmLabel = RhythmChoice.Normal.linearLabel)
        return thought.id
    }

    private fun newTopic(issueId: String, identifier: String, title: String, due: LocalDate) = TopicEntity(
        issueId = issueId, identifier = identifier, title = title, url = "",
        sentences = emptyList(), step = null, intervalFrom = null, intervalTo = null,
        rhythm = Rhythm.Normal.name, intervalFactor = 1.0,
        nextDueEpochDay = due.toEpochDay(), inRound = false, unhandledRounds = 0,
        sentenceIndex = 0, sentenceUses = 0, linearStateType = "triage",
        status = TopicStatus.Active, lastSyncedAt = 0,
    )

    /**
     * Refreshes all topics from Linear in one request. Fields with a change still on
     * its way to Linear keep the local value. Returns false if Linear was not reachable.
     */
    suspend fun refresh(today: LocalDate = LocalDate.now()): Boolean {
        val key = settings.apiKey() ?: return false
        val topics = db.topics().open()
        if (topics.isEmpty()) return true
        val issues = runCatching { linear.issues(key, topics.map { it.issueId }) }.getOrNull() ?: return false
        val pending = db.edits().all().associateBy { it.issueId }
        val byId = issues.associateBy { it.id }
        val now = System.currentTimeMillis()
        for (t in topics) {
            val i = byId[t.issueId] ?: continue
            val edit = pending[t.issueId]
            val block = BearBlock.find(i.description)?.parsed?.block
            var u = t.copy(identifier = i.identifier, url = i.url, description = i.description, linearStateType = i.stateType, lastSyncedAt = now)
            if (edit?.title == null) u = u.copy(title = i.title)
            if (edit?.block != true && block != null) {
                u = u.copy(sentences = block.sentences, step = block.step, intervalFrom = block.interval?.first, intervalTo = block.interval?.last)
            }
            val fromLabel = i.bearLabel?.let { RhythmChoice.fromLinearLabel(it.name) }
            if (edit?.rhythmLabel == null && fromLabel != null && fromLabel != t.choice()) u = u.withChoice(fromLabel, today, resume = false)
            if (i.ended) u = u.copy(status = TopicStatus.Ended, inRound = false)
            db.topics().upsert(u)
        }
        settings.markSynced(now)
        return true
    }

    /** Called when a round card is finished. Rotates the sentence and plans the next due day. */
    suspend fun finishRound(issueId: String, feedback: Feedback, confirmedWithSentence: Boolean, today: LocalDate = LocalDate.now()) {
        val t = db.topics().get(issueId) ?: return
        val factor = RoundPlanner.adjustFactor(t.intervalFactor, feedback, confirmedWithSentence)
        val days = RoundPlanner.effectiveDays(Rhythm.valueOf(t.rhythm), factor, t.override())
        val nextIndex = if (t.sentences.size > 1) (t.sentenceIndex + 1) % t.sentences.size else 0
        db.topics().upsert(
            t.copy(
                intervalFactor = factor,
                nextDueEpochDay = RoundPlanner.nextDueDate(today, days).toEpochDay(),
                inRound = false, unhandledRounds = 0,
                sentenceIndex = nextIndex,
                sentenceUses = if (confirmedWithSentence) t.sentenceUses + 1 else t.sentenceUses,
            ),
        )
    }

    /** A step changed during a round. It reaches Linear through the edit queue. */
    suspend fun updateStep(issueId: String, step: String) {
        val t = db.topics().get(issueId) ?: return
        val clean = step.trim().ifEmpty { null }
        if (clean == t.step) return
        db.topics().upsert(t.copy(step = clean))
        edits.record(issueId, block = true)
    }

    /**
     * Saves the core fields from the entry view. Only what really changed is marked
     * for Linear; the Bear block is written only if sentences or step changed.
     */
    suspend fun save(issueId: String, title: String, sentences: List<String>, step: String, choice: RhythmChoice, today: LocalDate = LocalDate.now()) {
        val t = db.topics().get(issueId) ?: return
        val cleanTitle = title.trim().ifEmpty { t.title }
        val cleanSentences = sentences.map { it.trim() }.filter { it.isNotEmpty() }.take(BearBlock.MAX_SENTENCES)
        val cleanStep = step.trim().ifEmpty { null }
        var u = t.copy(title = cleanTitle, sentences = cleanSentences, step = cleanStep)
        if (cleanSentences != t.sentences) u = u.copy(sentenceIndex = 0, sentenceUses = 0)
        val choiceChanged = choice != t.choice() || (t.status == TopicStatus.Paused && choice != RhythmChoice.Merken)
        if (choiceChanged) u = u.withChoice(choice, today)
        db.topics().upsert(u)
        edits.record(
            issueId,
            title = cleanTitle.takeIf { it != t.title },
            block = cleanSentences != t.sentences || cleanStep != t.step,
            rhythmLabel = choice.linearLabel.takeIf { choice != t.choice() },
        )
    }

    suspend fun answerStuck(issueId: String, answer: StuckAnswer, today: LocalDate = LocalDate.now()) {
        val t = db.topics().get(issueId) ?: return
        val fresh = t.copy(inRound = false, unhandledRounds = 0)
        db.topics().upsert(
            when (answer) {
                StuckAnswer.Seltener -> {
                    val factor = RoundPlanner.adjustFactor(t.intervalFactor, Feedback.Seltener, confirmedWithSentence = false)
                    val days = RoundPlanner.effectiveDays(Rhythm.valueOf(t.rhythm), factor, t.override())
                    fresh.copy(intervalFactor = factor, nextDueEpochDay = RoundPlanner.nextDueDate(today, days).toEpochDay())
                }
                StuckAnswer.PasstSo -> fresh.copy(nextDueEpochDay = RoundPlanner.nextDueDate(today, t.days()).toEpochDay())
                StuckAnswer.Pausieren -> fresh.copy(status = TopicStatus.Paused)
                StuckAnswer.NichtMehrWichtig -> fresh.copy(status = TopicStatus.Ended)
            },
        )
    }

    /** Brings a paused topic back into the rounds. */
    suspend fun resume(issueId: String, today: LocalDate = LocalDate.now()) {
        val t = db.topics().get(issueId) ?: return
        db.topics().upsert(t.copy(status = TopicStatus.Active, nextDueEpochDay = RoundPlanner.nextDueDate(today, t.days()).toEpochDay()))
    }

    /** Stops the reminders. Nothing is changed or deleted in Linear. */
    suspend fun forget(issueId: String) {
        val t = db.topics().get(issueId) ?: return
        db.topics().upsert(t.copy(status = TopicStatus.Ended, inRound = false, unhandledRounds = 0))
    }

    /** A probe round in the first-run guide: the topic was shown, but nothing about its rhythm changes. */
    suspend fun endProbe(issueId: String) {
        val t = db.topics().get(issueId) ?: return
        db.topics().upsert(t.copy(inRound = false))
    }

    /** Puts a topic into a probe round right away, without an alarm. */
    suspend fun startProbe(issueId: String) {
        val t = db.topics().get(issueId) ?: return
        db.topics().upsert(t.copy(inRound = true))
    }

    suspend fun later(issueId: String, today: LocalDate = LocalDate.now()) {
        val t = db.topics().get(issueId) ?: return
        db.topics().upsert(t.copy(inRound = false, nextDueEpochDay = today.plusDays(1).toEpochDay()))
    }

    /** The „Später“ action on the notification: every waiting topic comes back tomorrow. */
    suspend fun laterAll(today: LocalDate = LocalDate.now()) = db.topics().inRound().forEach { later(it.issueId, today) }
}

/** The chip that matches the topic's current rhythm and status. */
fun TopicEntity.choice(): RhythmChoice =
    if (status == TopicStatus.Remembered) RhythmChoice.Merken
    else RhythmChoice.entries.first { it.rhythm?.name == rhythm }

/**
 * Applies a rhythm choice. A new rhythm starts fresh (factor 1, a new due day inside
 * its range). [resume] brings a paused topic back; a change read from Linear does not.
 */
fun TopicEntity.withChoice(choice: RhythmChoice, today: LocalDate, resume: Boolean = true): TopicEntity {
    if (choice == RhythmChoice.Merken) return copy(status = TopicStatus.Remembered, inRound = false, unhandledRounds = 0)
    val rhythm = choice.rhythm!!
    val status = if (status == TopicStatus.Remembered || (resume && status == TopicStatus.Paused)) TopicStatus.Active else status
    if (rhythm.name == this.rhythm) return copy(status = status)
    val days = RoundPlanner.effectiveDays(rhythm, 1.0, override())
    return copy(rhythm = rhythm.name, intervalFactor = 1.0, status = status, nextDueEpochDay = RoundPlanner.nextDueDate(today, days).toEpochDay())
}

fun TopicEntity.override(): IntRange? = if (intervalFrom != null && intervalTo != null) intervalFrom..intervalTo else null

fun TopicEntity.days(): IntRange = RoundPlanner.effectiveDays(Rhythm.valueOf(rhythm), intervalFactor, override())

fun TopicEntity.currentSentence(): String? = sentences.getOrNull(sentenceIndex.coerceIn(0, (sentences.size - 1).coerceAtLeast(0)))

