class MainActivity : ComponentActivity() {
    private val openRound = mutableIntStateOf(0)
    private val openEntry = mutableStateOf<OpenEntry?>(null)

    override fun onCreate(savedInstanceState: Bundle?) {
        enableEdgeToEdge()
        super.onCreate(savedInstanceState)
        if (intent.getBooleanExtra(Notifications.EXTRA_OPEN_ROUND, false)) openRound.intValue++
        // Only on a fresh start. After a rotation or a restart from saved state this intent was
        // handled already; a new tap on a widget arrives through onNewIntent.
        if (savedInstanceState == null) takeEntry(intent)
        setContent { BearTheme { BearAppUi(openRound.intValue, openEntry.value) } }
    }

    override fun onNewIntent(intent: Intent) {
        super.onNewIntent(intent)
        if (intent.getBooleanExtra(Notifications.EXTRA_OPEN_ROUND, false)) openRound.intValue++
        takeEntry(intent)
    }

    private fun takeEntry(intent: Intent) {
        val id = intent.getStringExtra(EXTRA_OPEN_ENTRY) ?: return
        openEntry.value = OpenEntry(id, (openEntry.value?.count ?: 0) + 1)
    }

    companion object {
        /** An entry to open, from a widget. */
        const val EXTRA_OPEN_ENTRY = "open_entry"
    }
}

/** The count lets the same entry open again after going back. */
data class OpenEntry(val id: String, val count: Int)

@Composable
fun BearAppUi(
    openRoundSignal: Int,
    openEntrySignal: OpenEntry? = null,
    vm: BearViewModel = viewModel(factory = BearViewModel.Factory),
    guide: OnboardingViewModel = viewModel(factory = OnboardingViewModel.Factory),
) {
    val gate by guide.gate.collectAsStateWithLifecycle()
    val settings by vm.settings.collectAsStateWithLifecycle()
    CompositionLocalProvider(LocalBearName provides settings.bearName) {
        when (gate) {
            // Paper only, so neither the guide nor the home screen flashes up before the settings are read.
            Gate.Loading -> Box(Modifier.fillMaxSize().background(Bear.palette.paper))
            Gate.Guide -> {
                val round by vm.round.collectAsStateWithLifecycle()
                OnboardingRoute(guide, round, openRoundSignal)
            }
            Gate.App -> MainScreens(openRoundSignal, openEntrySignal, vm)
        }
    }
}

@Composable
private fun MainScreens(openRoundSignal: Int, openEntrySignal: OpenEntry?, vm: BearViewModel) {
    val context = LocalContext.current
    var dest by rememberSaveable { mutableStateOf(Destination.Home) }
    var entryId by rememberSaveable { mutableStateOf<String?>(null) }
    // Coming back from an entry returns to the open list, as the user left it.
    var sheetOpen by rememberSaveable { mutableStateOf(false) }
    var entryFromSheet by rememberSaveable { mutableStateOf(false) }
    LaunchedEffect(openRoundSignal) { if (openRoundSignal > 0) dest = Destination.Round }

    fun openEntry(id: String, fromSheet: Boolean) {
        vm.openEntry(id)
        entryId = id
        entryFromSheet = fromSheet
        sheetOpen = false
        dest = Destination.Entry
    }

    LaunchedEffect(openEntrySignal) { openEntrySignal?.let { openEntry(it.id, fromSheet = false) } }

    fun back() {
        if (dest == Destination.Entry && entryFromSheet) sheetOpen = true
        dest = Destination.Home
    }
    BackHandler(dest != Destination.Home) { back() }

    val home by vm.home.collectAsStateWithLifecycle()
    val entries by vm.entries.collectAsStateWithLifecycle()
    val round by vm.round.collectAsStateWithLifecycle()
    val settings by vm.settings.collectAsStateWithLifecycle()
    val topicUi by vm.topicUi.collectAsStateWithLifecycle()
    val connectUi by vm.connectUi.collectAsStateWithLifecycle()
    val log by vm.roundLog.collectAsStateWithLifecycle()
    val entry by vm.entry.collectAsStateWithLifecycle()
    val draft by vm.draft.collectAsStateWithLifecycle()
    val savedNote by vm.savedNote.collectAsStateWithLifecycle()

    val notificationPermission = rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()) { }
    var reliabilityTick by remember { mutableIntStateOf(0) }

    AnimatedContent(dest, transitionSpec = { fadeIn() togetherWith fadeOut() }, label = "screen") { screen ->
        when (screen) {
            Destination.Home -> HomeRoute(
                home, entries, sheetOpen, onSheet = { sheetOpen = it },
                onSave = { vm.capture(it) }, onOpen = { dest = it }, onOpenEntry = { openEntry(it, fromSheet = sheetOpen) },
            )
            Destination.Round -> when (val r = round) {
                RoundState.Loading -> Unit
                RoundState.None -> LaunchedEffect(Unit) { dest = Destination.Home }
                is RoundState.Show -> AnimatedContent(r.ui, contentKey = { it.issueId }, transitionSpec = { fadeIn() togetherWith fadeOut() }, label = "topic") { ui ->
                    // One card per topic; a finished topic leaves the round and the next one follows.
                    RoundRoute(
                        ui,
                        onFinish = { f, confirmed, step -> vm.finishRound(ui.issueId, f, confirmed, step) },
                        onLater = { vm.later(ui.issueId) },
                        onBack = { dest = Destination.Home },
                    )
                }
            }
            Destination.Entry -> {
                val e = entry
                val d = draft
                if (e != null && d != null && e.id == entryId) {
                    EntryContent(
                        e, d, savedNote,
                        EntryActions(
                            onDraft = { vm.editDraft(it) },
                            onSave = { vm.saveEntry() },
                            onMakeTopic = {
                                vm.makeTopic()
                                // A topic means rounds, and rounds need notifications.
                                notificationPermission.launch(Manifest.permission.POST_NOTIFICATIONS)
                            },
                            onAnswerStuck = { vm.answerStuck(it) },
                            onResume = { vm.resume() },
                            onForget = { vm.forget { back() } },
                            onOpenRound = { dest = Destination.Round },
                            onOpenLinear = { url -> context.startActivity(Intent(Intent.ACTION_VIEW, Uri.parse(url))) },
                            onBack = { back() },
                        ),
                    )
                }
            }
            Destination.Topic -> TopicContent(
                ui = topicUi.copy(connected = settings.hasApiKey),
                onQuery = { vm.onTopicQuery(it) },
                onLoad = { vm.loadTopic() },
                onAdopt = {
                    vm.adoptTopic { id -> openEntry(id, fromSheet = false) }
                    notificationPermission.launch(Manifest.permission.POST_NOTIFICATIONS)
                },
                onToggleExample = { vm.toggleExample() },
                onConnect = { dest = Destination.Connect },
                onBack = { dest = Destination.Home },
            )
            Destination.Connect -> ConnectContent(
                ui = connectUi.copy(connectedAs = connectUi.connectedAs ?: settings.connectedAs.takeIf { connectUi.key.isEmpty() }),
                onKey = { vm.onKey(it) },
                onConnect = { vm.connect() },
                onOpenLinear = { context.startActivity(Intent(Intent.ACTION_VIEW, Uri.parse("https://linear.app/settings/account/security"))) },
                onBack = { dest = Destination.Home },
            )
            Destination.Reliability -> {
                val status = remember(reliabilityTick) { (context.applicationContext as BearApp).container.reliability.status() }
                LaunchedEffect(Unit) { reliabilityTick++ }
                ReliabilityContent(
                    ui = ReliabilityUi(
                        notifications = status.notifications,
                        batteryUnrestricted = status.batteryUnrestricted,
                        bucket = status.bucket,
                        exactAlarms = status.exactAlarms,
                        linear = settings.connectedAs?.let { name ->
                            "verbunden" + (settings.lastSyncAt?.let { " · ${Words.time(it)}" } ?: "")
                        } ?: "nicht verbunden",
                        nextRound = settings.nextRoundAt?.let { Words.time(it) },
                        log = log,
                    ),
                    onAllowNotifications = { notificationPermission.launch(Manifest.permission.POST_NOTIFICATIONS); reliabilityTick++ },
                    onBattery = {
                        context.startActivity(Intent(Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS, Uri.parse("package:${context.packageName}")))
                    },
                    onProbe = { vm.probe() },
                    onBack = { dest = Destination.Home },
                )
            }
            Destination.Settings -> PreferencesContent(
                PreferencesUi(
                    name = settings.bearName,
                    windows = settings.windows,
                    nextRound = settings.nextRoundAt?.let { "Nächste Runde: ${Words.nextRoundBetween(it, settings.windows)}." },
                ),
                onRename = { vm.rename(it) },
                onWindows = { vm.setWindows(it) },
                onBack = { dest = Destination.Home },
            )
        }
    }
}

