        verticalArrangement = Arrangement.Bottom,
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        BearFigure(
            when {
                saved -> BearMood.LegtAb
                draft.isNotBlank() -> BearMood.HoertZu
                else -> BearMood.Ruhig
            },
            Modifier.width(112.dp), animate = animate,
        )
        Spacer(Modifier.height(16.dp))
        AnimatedContent(saved, transitionSpec = { fadeIn() togetherWith fadeOut() }, label = "saved") { isSaved ->
            if (isSaved) {
                Text(
                    "Liegt sicher bei mir.",
                    style = MaterialTheme.typography.headlineSmall, color = p.ink,
                    modifier = Modifier.fillMaxWidth().padding(vertical = 18.dp),
                )
            } else {
                BearTextField(
                    value = draft, onValueChange = onDraft, placeholder = "Was soll ich mir merken?",
                    modifier = Modifier.focusRequester(focus),
                    keyboardOptions = KeyboardOptions(capitalization = KeyboardCapitalization.Sentences, imeAction = ImeAction.Send),
                    keyboardActions = KeyboardActions(onSend = { onSave() }),
                    trailing = { SendButton(visible = draft.isNotBlank(), onClick = onSave) },
                )
            }
        }
    }
}

