/** Stateful wrapper: draft text and the bear's reaction to typing and saving. */
@Composable
fun HomeRoute(
    ui: HomeUi,
    entries: EntriesUi,
    sheetOpen: Boolean,
    onSheet: (Boolean) -> Unit,
    onSave: (String) -> Unit,
    onOpen: (Destination) -> Unit,
    onOpenEntry: (String) -> Unit,
) {
    var draft by rememberSaveable { mutableStateOf("") }
    var lastTyped by remember { mutableLongStateOf(0L) }
    var tick by remember { mutableIntStateOf(0) }
    var justSavedAt by remember { mutableLongStateOf(0L) }
    val haptics = LocalHapticFeedback.current

    LaunchedEffect(lastTyped) { delay(750); tick++ }
    LaunchedEffect(justSavedAt) { if (justSavedAt > 0) { delay(1400); tick++ } }

    val now = remember(tick, draft, justSavedAt) { System.currentTimeMillis() }
    val mood = when {
        justSavedAt > 0 && now - justSavedAt < 1400 -> BearMood.LegtAb
        draft.isNotBlank() && now - lastTyped < 750 -> BearMood.HoertZu
        draft.isNotBlank() -> BearMood.DenktNach
        ui.sleeping -> BearMood.Schlaeft
        ui.waitingTitles.isNotEmpty() -> BearMood.BringtZettel
        ui.hint != null && ui.latest == null -> BearMood.Winkt
        else -> BearMood.Ruhig
    }
    HomeContent(
        ui = ui, draft = draft, mood = mood,
        onDraftChange = { draft = it; lastTyped = System.currentTimeMillis() },
        onSave = {
            if (draft.isNotBlank()) {
                onSave(draft); draft = ""; justSavedAt = System.currentTimeMillis()
                haptics.performHapticFeedback(HapticFeedbackType.Confirm)
            }
        },
        onShowEntries = { onSheet(true) },
        onOpen = onOpen,
        onOpenEntry = onOpenEntry,
    )
    if (sheetOpen) {
        EntriesSheet(
            entries,
            onDismiss = { onSheet(false) },
            onOpen = onOpenEntry,
            onAddTopic = { onSheet(false); onOpen(Destination.Topic) },
        )
    }
}

/**
 * Editorial home: a large greeting, the bear's voice in italic, the bear sitting
 * at the edge of the screen, and one input at the bottom.
 */
@OptIn(ExperimentalLayoutApi::class)
@Composable
fun HomeContent(
    ui: HomeUi,
    draft: String,
    mood: BearMood,
    onDraftChange: (String) -> Unit,
    onSave: () -> Unit,
    onShowEntries: () -> Unit,
    onOpen: (Destination) -> Unit,
    onOpenEntry: (String) -> Unit,
    animate: Boolean = true,
    menuOpen: Boolean = false,
) {
    val p = Bear.palette
    var menu by remember { mutableStateOf(menuOpen) }
    val typing = draft.isNotBlank()
    // While the keyboard is open, the voice line stays hidden, also right after sending.
    // Otherwise it would come back and squeeze the bear.
    val compact = typing || WindowInsets.isImeVisible
    val voice = when {
        ui.hint != null -> ui.hint
        ui.sleeping -> "Pst. Festhalten geht trotzdem."
        ui.waitingTitles.isNotEmpty() -> "Ich habe dir etwas mitgebracht."
        ui.stuckTitle != null -> "Das hier ist liegen geblieben."
        else -> "Was geht dir durch den Kopf?"
    }

    Column(
        Modifier.fillMaxSize().background(p.paper).safeDrawingPadding().imePadding().padding(horizontal = 26.dp),
    ) {
        Box(Modifier.fillMaxWidth().padding(top = 6.dp)) {
            Text(
                ui.dateLabel.uppercase(), style = MaterialTheme.typography.labelMedium, color = p.inkFaint,
                modifier = Modifier.align(Alignment.CenterStart),
            )
            Box(Modifier.align(Alignment.CenterEnd).offset(x = 10.dp)) {
                RoundIconButton(BearIcons.More, "Mehr", { menu = true })
                DropdownMenu(expanded = menu, onDismissRequest = { menu = false }, shape = RoundedCornerShape(18.dp), containerColor = p.card) {
                    MenuItem("Thema holen") { menu = false; onOpen(Destination.Topic) }
                    MenuItem("Linear") { menu = false; onOpen(Destination.Connect) }
                    MenuItem("Zuverlässigkeit") { menu = false; onOpen(Destination.Reliability) }
                    MenuItem("Einstellungen") { menu = false; onOpen(Destination.Settings) }
                }
            }
        }
        Spacer(Modifier.height(18.dp))
        Text(ui.greeting, style = MaterialTheme.typography.displayLarge, color = p.ink)
        AnimatedVisibility(!compact, enter = fadeIn() + expandVertically(), exit = fadeOut() + shrinkVertically()) {
            AnimatedContent(voice, transitionSpec = { fadeIn() togetherWith fadeOut() }, label = "voice") { line ->
                Text(line, style = VoiceStyle, color = p.inkSoft)
            }
        }
        Spacer(Modifier.height(18.dp))
        ui.status?.let { status ->
            Row {
                Text(status, style = MaterialTheme.typography.bodyMedium, color = p.inkSoft)
                if (ui.statusAction != null && ui.statusTarget != null) {
                    Text(
                        "  " + ui.statusAction, style = MaterialTheme.typography.bodyMedium.copy(textDecoration = TextDecoration.Underline),
                        color = p.ink, modifier = Modifier.clickable(role = Role.Button) { onOpen(ui.statusTarget) },
                    )
                }
            }
        }
        // The bear stands in whatever space is left above the input and leans out of the
        // screen edge. It shrinks with the keyboard or a longer list and steps aside when
        // there is too little room. The name is not shown here (Steven, 27 September); TalkBack still hears it.
        BearStage(mood, Modifier.weight(1f), name = ui.bearName, animate = animate)
        if (ui.stuckId != null && ui.stuckTitle != null) {
            NoteCard("Dreimal liegen geblieben", ui.stuckTitle, "Soll ich es seltener bringen?") { onOpenEntry(ui.stuckId) }
        }
        ui.waitingTitles.firstOrNull()?.let { first ->
            val more = ui.waitingTitles.size - 1
            NoteCard(
                if (more == 0) "Ein Thema wartet" else "${ui.waitingTitles.size} Themen warten", first,
                if (more == 0) null else if (more == 1) "und eins mehr" else "und $more weitere",
            ) { onOpen(Destination.Round) }
        }
        RecentSection(ui, onShowEntries) { onOpen(Destination.Connect) }
        Spacer(Modifier.height(10.dp))
        BearTextField(
            value = draft,
            onValueChange = onDraftChange,
            placeholder = "Einfach lostippen …",
            maxLines = 6,
            keyboardOptions = KeyboardOptions(capitalization = KeyboardCapitalization.Sentences, imeAction = ImeAction.Send),
            keyboardActions = KeyboardActions(onSend = { onSave() }),
            trailing = { SendButton(visible = draft.isNotBlank(), onClick = onSave) },
        )
        Spacer(Modifier.height(14.dp))
    }
}

@Composable
private fun MenuItem(text: String, onClick: () -> Unit) {
