/** A card for what the bear brought: a waiting topic or one that was left lying. */
@Composable
private fun NoteCard(label: String, title: String, detail: String?, onClick: () -> Unit) {
    val p = Bear.palette
    Row(
        Modifier
            .fillMaxWidth()
            .padding(bottom = 12.dp)
            .softShadow(p.card, 22.dp, p.shadow)
            .clip(RoundedCornerShape(22.dp))
            .background(p.card)
            .clickable(role = Role.Button, onClick = onClick)
            .padding(start = 20.dp, end = 12.dp, top = 16.dp, bottom = 16.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Column(Modifier.weight(1f)) {
            Text(label.uppercase(), style = MaterialTheme.typography.labelMedium, color = p.inkFaint)
            Spacer(Modifier.height(4.dp))
            Text(title, style = MaterialTheme.typography.titleLarge, color = p.ink, maxLines = 2, overflow = TextOverflow.Ellipsis)
            detail?.let {
                Spacer(Modifier.height(2.dp))
