            }
        }
        Icon(BearIcons.Chevron, null, tint = p.inkSoft, modifier = Modifier.size(20.dp))
    }
}

/** The latest thought's state, and the way into the list of all entries. */
@Composable
private fun RecentSection(ui: HomeUi, onShowEntries: () -> Unit, onFix: () -> Unit) {
    val p = Bear.palette
    Column(Modifier.fillMaxWidth()) {
        ui.latest?.let { SavedLine(it, ui.connected, onFix) }
        if (ui.entryCount > 0) {
            Row(
                Modifier
                    .clip(RoundedCornerShape(12.dp))
                    .clickable(role = Role.Button, onClick = onShowEntries)
                    .padding(vertical = 8.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Text("Deine Einträge · ${ui.entryCount}", style = MaterialTheme.typography.bodyMedium, color = p.inkSoft)
                Icon(BearIcons.ChevronUp, null, tint = p.inkFaint, modifier = Modifier.padding(start = 4.dp).size(16.dp))
            }
        }
    }
}

@Composable
private fun SavedLine(row: ThoughtRow, connected: Boolean, onFix: () -> Unit) {
    val p = Bear.palette
    val inLinear = row.state == ThoughtState.InLinear
    Row(Modifier.fillMaxWidth().padding(vertical = 6.dp), verticalAlignment = Alignment.Top) {
        Icon(if (inLinear) BearIcons.Check else BearIcons.Phone, null, tint = p.ink, modifier = Modifier.padding(top = 2.dp).size(18.dp))
        Spacer(Modifier.width(10.dp))
        Column(Modifier.weight(1f)) {
            Text(Words.thoughtState(row), style = MaterialTheme.typography.bodyMedium, color = p.ink)
            val detail = when {
                row.state == ThoughtState.NeedsAttention -> "Tippe hier, um die Verbindung zu prüfen"
                !connected && !inLinear -> "Nach Linear geht es, sobald du verbunden bist"
                row.state == ThoughtState.Local -> "Nach Linear geht es, sobald Netz da ist"
                else -> null
            }
            detail?.let {
                Text(
                    it, style = MaterialTheme.typography.bodyMedium, color = p.inkFaint,
                    modifier = if (row.state == ThoughtState.NeedsAttention || !connected) Modifier.clickable(onClick = onFix) else Modifier,
                )
            }
        }
    }
}

