@OptIn(ExperimentalCoroutinesApi::class)
class BearViewModel(private val c: AppContainer) : ViewModel() {

    val settings: StateFlow<BearSettings> = c.settings.settings.stateIn(viewModelScope, SharingStarted.Eagerly, BearSettings())
    private val topics: StateFlow<List<TopicEntity>> = c.topics.observeAll().stateIn(viewModelScope, SharingStarted.Eagerly, emptyList())
    private val thoughts: StateFlow<List<ThoughtEntity>> = c.thoughts.observe().stateIn(viewModelScope, SharingStarted.Eagerly, emptyList())
    val roundLog: StateFlow<List<RoundLogRow>> = c.db.rounds().observeRecent().map { list -> list.map(::logRow) }
        .stateIn(viewModelScope, SharingStarted.Eagerly, emptyList())

    val entries: StateFlow<EntriesUi> = combine(topics, thoughts) { t, th -> buildEntries(t, th) }
        .stateIn(viewModelScope, SharingStarted.Eagerly, EntriesUi())

    val home: StateFlow<HomeUi> = combine(settings, thoughts, topics, entries) { s, th, t, e -> buildHome(s, th, t, e) }
        .stateIn(viewModelScope, SharingStarted.Eagerly, HomeUi())

    /** Straight from the database, so a cold start from the notification waits for real data. */
    val round: StateFlow<RoundState> = combine(c.topics.observeAll(), c.settings.settings) { t, s -> buildRound(t, s) }
        .stateIn(viewModelScope, SharingStarted.Eagerly, RoundState.Loading)

    val topicUi = MutableStateFlow(TopicUi())
    val connectUi = MutableStateFlow(ConnectUi())
    private var preview: TopicPreview? = null

    // ---- entry view ----
    private val entryId = MutableStateFlow<String?>(null)
    val entry: StateFlow<EntryUi?> = entryId.flatMapLatest { id ->
        if (id == null) flowOf(null)
        else combine(c.topics.observe(id), c.thoughts.observe(id), c.edits.observe(), settings) { t, th, e, s ->
            buildEntry(id, t?.takeIf { it.status != TopicStatus.Ended }, th, e.firstOrNull { it.issueId == id }, s)
        }
    }.stateIn(viewModelScope, SharingStarted.Eagerly, null)
    val draft = MutableStateFlow<EntryDraft?>(null)
    val savedNote = MutableStateFlow<String?>(null)
    private var draftBase: EntryDraft? = null

    init {
        viewModelScope.launch {
            c.scheduler.restore()
            c.thoughts.resendPending()
            c.edits.enqueueAll()
            if (c.topics.refresh()) c.scheduler.scheduleNext()
        }
        // Keep the draft in step with the entry, unless something is being edited.
        viewModelScope.launch {
            entry.collect { e ->
                if (e == null) return@collect
                val fresh = e.toDraft()
                val d = draft.value
                if (d == null || d.id != e.id || d.isTopic != e.isTopic || d == draftBase) draft.value = fresh
                draftBase = fresh
            }
        }
    }

    // ---- capture ----
    fun capture(text: String) = viewModelScope.launch {
        c.thoughts.capture(text)
        val seen = settings.value.hintsSeen
        c.settings.markHint(if (Hints.CAPTURE !in seen) Hints.CAPTURE else Hints.SAVED)
    }

    // ---- round ----
    fun finishRound(issueId: String, feedback: Feedback, confirmedWithSentence: Boolean, newStep: String?) = viewModelScope.launch {
        c.topics.finishRound(issueId, feedback, confirmedWithSentence)
        newStep?.let { c.topics.updateStep(issueId, it) }
        c.settings.markHint(Hints.ROUND)
        afterRoundChange()
    }

    fun later(issueId: String) = viewModelScope.launch {
        c.topics.later(issueId)
        afterRoundChange()
    }

    private suspend fun afterRoundChange() {
        if (c.db.topics().inRound().isEmpty()) Notifications.cancelRound(c.appContext)
        c.scheduler.scheduleNext()
    }

    fun probe() = viewModelScope.launch { c.scheduler.scheduleProbe() }

    // ---- settings ----

    /** Confirmed on the settings page. The notification channel follows via [app.kiumu.bear.BearApp]. */
    fun rename(name: String) = viewModelScope.launch { BearName.clean(name)?.let { c.settings.setBearName(it) } }

    fun setWindows(windows: List<RoundWindow>) = viewModelScope.launch {
        c.settings.setWindows(windows)
        c.scheduler.scheduleNext()
    }

    // ---- entry view ----
    fun openEntry(id: String) {
        if (entryId.value != id) {
            draft.value = null
            draftBase = null
            savedNote.value = null
        }
        entryId.value = id
    }

    fun editDraft(change: (EntryDraft) -> EntryDraft) {
        draft.update { it?.let(change) }
        savedNote.value = null
    }

    fun saveEntry() = viewModelScope.launch {
        val d = draft.value ?: return@launch
        if (d.isTopic) {
            c.topics.save(d.id, d.title, d.sentences, d.step, d.choice)
            c.scheduler.scheduleNext()
        } else {
            c.thoughts.rename(d.id, d.title)
        }
        // Marked as unedited, so the next entry update (with the cleaned, saved values) replaces it.
        draftBase = d
        savedNote.value = if (settings.value.hasApiKey) "Gesichert. Linear bekommt es gleich." else "Gesichert. Nach Linear geht es, sobald du verbunden bist."
    }

    fun makeTopic() = viewModelScope.launch {
        val id = entryId.value ?: return@launch
        val thought = c.db.thoughts().get(id) ?: return@launch
        c.topics.fromThought(thought)
        c.scheduler.scheduleNext()
    }

    fun answerStuck(answer: StuckAnswer) = viewModelScope.launch {
        val id = entryId.value ?: return@launch
        c.topics.answerStuck(id, answer)
        c.scheduler.scheduleNext()
    }

    fun resume() = viewModelScope.launch {
        entryId.value?.let { c.topics.resume(it) }
        c.scheduler.scheduleNext()
    }

    fun forget(onDone: () -> Unit) = viewModelScope.launch {
        entryId.value?.let { c.topics.forget(it) }
        c.scheduler.scheduleNext()
        onDone()
    }

    // ---- topic from Linear ----
    fun onTopicQuery(q: String) = topicUi.update { it.copy(query = q, error = null, preview = if (q != it.query) null else it.preview) }
    fun toggleExample() = topicUi.update { it.copy(showExample = !it.showExample) }

    fun loadTopic() = viewModelScope.launch {
        topicUi.update { it.copy(loading = true, error = null, preview = null) }
        val result = runCatching { c.topics.preview(topicUi.value.query) }
        val p = result.getOrNull()
        preview = p
        topicUi.update {
            it.copy(
                loading = false,
                preview = p?.let { pv -> TopicCard(pv.issue.identifier, pv.issue.title, pv.block.sentences.size, pv.block.step, pv.problems.map { pr -> "Zeile ${pr.line}: ${pr.message}" }, pv.known) },
                error = when {
                    result.isFailure -> (result.exceptionOrNull() as? LinearException)?.message ?: "Das hat nicht geklappt."
                    p == null -> "Dieses Issue finde ich nicht."
                    else -> null
                },
            )
        }
    }

    fun adoptTopic(onDone: (String) -> Unit) = viewModelScope.launch {
        val p = preview ?: return@launch
        val id = c.topics.adopt(p)
        c.scheduler.scheduleNext()
        topicUi.value = TopicUi()
        onDone(id)
    }

    // ---- connect ----
    fun onKey(k: String) = connectUi.update { it.copy(key = k.trim(), error = null, connectedAs = if (k.isEmpty()) null else it.connectedAs) }

    fun connect() = viewModelScope.launch {
        val key = connectUi.value.key
        connectUi.update { it.copy(busy = true, error = null) }
        try {
            val name = c.connectLinear(key)
            connectUi.value = ConnectUi(connectedAs = name)
        } catch (e: LinearException) {
            connectUi.update { it.copy(busy = false, error = e.message) }
        }
    }

    // ---- building UI state ----
    private fun buildEntries(topics: List<TopicEntity>, thoughts: List<ThoughtEntity>): EntriesUi {
        val (t, th) = entriesInOrder(topics, thoughts)
        return EntriesUi(
            topics = t.map { EntryCard(it.issueId, topicMeta(it), it.title, it.step, highlight = it.inRound || it.stuck) },
            thoughts = th.map { EntryCard(it.id, thoughtMeta(it), ThoughtText.split(it.text).first, null) },
        )
    }

    private fun topicMeta(t: TopicEntity): String {
        val where = t.identifier.ifEmpty { "Auf dem Telefon" }
        val state = when {
            t.inRound -> "wartet auf dich"
            t.stuck -> "liegen geblieben"
            t.status == TopicStatus.Remembered -> "nur merken"
            t.status == TopicStatus.Paused -> "pausiert"
            else -> Words.dueIn(t.nextDueEpochDay)
        }
        return "$where · $state"
    }

    private fun thoughtMeta(th: ThoughtEntity): String = when (th.state) {
        ThoughtState.InLinear -> "${th.identifier} · festgehalten"
        ThoughtState.NeedsAttention -> "Linear braucht dich"
        else -> "Auf dem Telefon"
    }

    private fun buildHome(s: BearSettings, thoughts: List<ThoughtEntity>, topics: List<TopicEntity>, entries: EntriesUi): HomeUi {
        val rows = thoughts.map { ThoughtRow(it.id, it.text, it.state, it.identifier, it.createdAt) }
        val now = System.currentTimeMillis()
        val latest = rows.firstOrNull()?.takeIf { now - it.createdAt < 30 * 60_000 }
        val hint = when {
            Hints.CAPTURE !in s.hintsSeen && rows.isEmpty() -> "Schreib einfach los. Ich halte es fest."
            Hints.CAPTURE in s.hintsSeen && Hints.SAVED !in s.hintsSeen && rows.size == 1 -> "Das war's schon. Ich halte alles fest."
            else -> null
        }
        val (status, action, target) = when {
            !s.hasApiKey -> Triple("Noch nicht mit Linear verbunden", "Verbinden", Destination.Connect)
            topics.isEmpty() -> Triple("Soll ich dir ein Thema bringen?", "Thema holen", Destination.Topic)
            s.nextRoundAt != null -> Triple("Nächste Runde: ${Words.nextRound(s.nextRoundAt)}", null, null)
            else -> Triple(null, null, null)
        }
        val hour = LocalTime.now().hour
        val zoned = ZonedDateTime.now()
        val stuck = topics.firstOrNull { it.stuck && it.status == TopicStatus.Active }
        return HomeUi(
            bearName = s.bearName,
            greeting = Words.greeting(zoned), dateLabel = Words.dateLabel(zoned),
            hint = hint, status = status, statusAction = action, statusTarget = target,
            latest = latest, connected = s.hasApiKey, entryCount = entries.count,
            waitingTitles = topics.filter { it.inRound && it.status == TopicStatus.Active }.sortedBy { it.nextDueEpochDay }.map { it.title },
            stuckId = stuck?.issueId, stuckTitle = stuck?.title,
            sleeping = hour >= 23 || hour < 6,
        )
    }

    private fun buildRound(topics: List<TopicEntity>, s: BearSettings): RoundState {
        val waiting = topics.filter { it.inRound && it.status == TopicStatus.Active }.sortedWith(compareBy({ it.nextDueEpochDay }, { it.issueId }))
        val t = waiting.firstOrNull() ?: return RoundState.None
        // Answered topics leave the round, so the count shows what is left.
        val next = Feedback.entries.associateWith { f ->
            val factor = RoundPlanner.adjustFactor(t.intervalFactor, f, confirmedWithSentence = t.sentences.isNotEmpty())
            RoundPlanner.describeNext(RoundPlanner.effectiveDays(Rhythm.valueOf(t.rhythm), factor, t.override()), s.windows)
        }
        return RoundState.Show(
            RoundUi(
                issueId = t.issueId,
                position = if (waiting.size > 1) "Noch ${waiting.size} Themen" else null,
                title = t.title,
                meta = listOf(t.identifier.ifEmpty { "Auf dem Telefon" }, "Rhythmus ${Rhythm.valueOf(t.rhythm).label}").joinToString(" · "),
                sentence = t.currentSentence(),
                step = t.step,
                next = next,
                showHint = Hints.ROUND !in s.hintsSeen,
            ),
        )
    }

    private fun buildEntry(id: String, t: TopicEntity?, th: ThoughtEntity?, edit: EditEntity?, s: BearSettings): EntryUi? {
        val sync = when {
            edit?.lastError != null -> "Linear braucht dich: ${edit.lastError}"
            edit != null && !s.hasApiKey -> "Änderungen liegen bei mir. Nach Linear gehen sie, sobald du verbunden bist."
            edit != null -> "Änderungen sind auf dem Weg nach Linear."
            else -> null
        }
        if (t != null) {
            val next = when {
                t.status == TopicStatus.Remembered -> "Kommt in keiner Runde. Du findest es hier."
                t.status == TopicStatus.Paused -> "Pausiert."
                t.inRound -> "Wartet in der Runde auf dich."
                t.stuck -> null
                else -> "Nächste Runde ${Words.dueIn(t.nextDueEpochDay)}, danach etwa alle ${t.days().let { if (it.first == it.last) "${it.first}" else "${it.first}–${it.last}" }} Tage."
            }
            val body = t.description?.let { d ->
                BearBlock.find(d)?.let { d.removeRange(it.range) } ?: d
            }?.trim()?.ifEmpty { null }
            return EntryUi(
                id = id, isTopic = true,
                meta = t.identifier.ifEmpty { "Auf dem Telefon" } + if (t.identifier.isNotEmpty()) " · In Linear" else "",
                title = t.title, sentences = t.sentences, step = t.step.orEmpty(), choice = t.choice(),
                next = next, body = body, url = t.url.ifEmpty { null },
                sync = sync, syncProblem = edit?.lastError != null,
                stuck = t.stuck, waiting = t.inRound, paused = t.status == TopicStatus.Paused,
            )
        }
        if (th == null) return null
        val title = ThoughtText.split(th.text).first
        // Below the title only what is not in it: the other lines, or everything if the title was shortened.
        val rest = th.text.trim().lines().drop(1).joinToString("\n").trim()
        val body = if (title.endsWith("…")) th.text.trim() else rest.ifEmpty { null }
        return EntryUi(
            id = id, isTopic = false,
            meta = when (th.state) {
                ThoughtState.InLinear -> "${th.identifier} · In Linear"
                ThoughtState.NeedsAttention -> "Linear braucht dich"
                else -> "Auf dem Telefon"
            },
            title = title,
            body = body,
            sync = sync ?: if (th.state != ThoughtState.InLinear && !s.hasApiKey) "Liegt sicher bei mir. Nach Linear geht es, sobald du verbunden bist." else null,
            syncProblem = edit?.lastError != null || th.state == ThoughtState.NeedsAttention,
        )
    }

    private fun logRow(e: RoundLogEntity): RoundLogRow {
        val label = (if (e.kind == RoundKind.Probe) "Probe · " else "") + Words.time(e.plannedAt)
        val detail = when {
            e.shownAt != null -> {
                val late = ((e.shownAt - e.plannedAt) / 60_000.0).roundToLong()
                if (late <= 0) "pünktlich" else "$late Min. später"
            }
            e.firedAt != null -> e.note ?: "ausgelöst"
            e.plannedAt > System.currentTimeMillis() -> "geplant"
            else -> e.note ?: "nicht gekommen"
        }
        return RoundLogRow(label, detail)
    }

    companion object {
        val Factory = viewModelFactory {
            initializer { BearViewModel((this[APPLICATION_KEY] as BearApp).container) }
        }
    }
}

package app.kiumu.bear

import android.app.Application
import android.content.Context
import app.kiumu.bear.alarm.RoundScheduler
