import app.kiumu.bear.data.TopicRepository
import app.kiumu.bear.data.db.BearDatabase
import app.kiumu.bear.data.linear.LinearClient
import app.kiumu.bear.data.settings.SettingsStore
import app.kiumu.bear.notify.Notifications
import app.kiumu.bear.widget.WidgetUpdates
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.distinctUntilChanged
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.launch

/** Hand-wired dependencies. The app is small enough not to need a DI framework. */
class AppContainer(context: Context) {
    val appContext: Context = context.applicationContext
    val db = BearDatabase.create(context)
    val settings = SettingsStore(context)
    val linear = LinearClient()
    val edits = EditQueue(context, db)
    val thoughts = ThoughtRepository(context, db, edits)
    val topics = TopicRepository(db, settings, linear, edits)
    val scheduler = RoundScheduler(context, db, settings)
    val reliability = Reliability(context)

    /**
     * Checks the key, stores it and sends whatever waited for it. Returns the Linear
     * user name. Used by the Linear page and by the first-run guide.
     */
    suspend fun connectLinear(key: String): String {
        val name = linear.viewerName(key)
        settings.saveConnection(key, name)
        runCatching { linear.inboxTarget(key) }.getOrNull()?.let { settings.saveInbox(it.teamId, it.triageStateId) }
        thoughts.resendPending()
        edits.enqueueAll()
        return name
    }

    /** An install from before the first-run guide: it already has thoughts, topics or a key. */
    suspend fun wasInUse(): Boolean =
        settings.current().hasApiKey || db.thoughts().count() > 0 || db.topics().open().isNotEmpty()
}

class BearApp : Application() {
    lateinit var container: AppContainer
        private set

    override fun onCreate() {
        super.onCreate()
        container = AppContainer(this)
        Notifications.createChannels(this)
        // The channel description names the bear; it follows a rename.
        CoroutineScope(SupervisorJob() + Dispatchers.Default).launch {
            container.settings.settings.map { it.bearName }.distinctUntilChanged().collect { Notifications.createChannels(this@BearApp, it) }
        }
        // Widgets show what is in the database; every change there reaches them.
        if (WidgetUpdates.anyPlaced(this)) WidgetUpdates.watch(this)
    }
}

