/** Sends one thought to INBOX. A lost answer never creates a second issue. */
class SendThoughtWorker(context: Context, params: WorkerParameters) : CoroutineWorker(context, params) {
    override suspend fun doWork(): Result {
        val c = (applicationContext as BearApp).container
        val id = inputData.getString(KEY_ID) ?: return Result.failure()
        val dao = c.db.thoughts()
        val thought = dao.get(id) ?: return Result.success()
        if (thought.state == ThoughtState.InLinear) return Result.success()
        val key = c.settings.apiKey() ?: return Result.success() // sent later, after connecting
        dao.upsert(thought.copy(state = ThoughtState.Sending))
        return try {
            val target = c.settings.inbox()?.let { InboxTarget(it.first, it.second) }
                ?: c.linear.inboxTarget(key).also { c.settings.saveInbox(it.teamId, it.triageStateId) }
            val (title, description) = ThoughtText.split(thought.text)
            val created = try {
                c.linear.createIssue(key, id, target, title, description)
            } catch (e: LinearException) {
                // The answer may have been lost after Linear created the issue. Look it up by our UUID.
                c.linear.issue(key, id)?.let { CreatedIssue(it.identifier, it.url) } ?: throw e
            }
            dao.upsert(thought.copy(state = ThoughtState.InLinear, identifier = created.identifier, lastError = null))
            // If the thought became a topic in the meantime, it now has its Linear identity,
            // and whatever was changed on it can follow.
            c.db.topics().get(id)?.let { c.db.topics().upsert(it.copy(identifier = created.identifier, url = created.url)) }
            if (c.db.edits().get(id) != null) c.edits.enqueue(id)
            Result.success()
        } catch (e: LinearException) {
            if (e.retryable) {
                dao.upsert(thought.copy(state = ThoughtState.Local, lastError = e.message))
                Result.retry()
            } else {
                dao.upsert(thought.copy(state = ThoughtState.NeedsAttention, lastError = e.message))
                Result.failure()
            }
        }
    }

    companion object { const val KEY_ID = "thought_id" }
}

/**
 * Runs when a round alarm fires. The first attempt has a network constraint and checks
 * Linear first; a delayed fallback without constraint shows the round anyway if the
 * phone has no network. Whichever comes first shows it; the other one stops.
 */
class RoundWorker(context: Context, params: WorkerParameters) : CoroutineWorker(context, params) {
    override suspend fun doWork(): Result {
        val c = (applicationContext as BearApp).container
        val logId = inputData.getLong(KEY_LOG, -1)
        val kind = RoundKind.valueOf(inputData.getString(KEY_KIND) ?: RoundKind.Regular.name)
        val entry = c.db.rounds().byId(logId)
        if (entry?.shownAt != null) return Result.success()

        if (!inputData.getBoolean(KEY_FALLBACK, false)) c.topics.refresh()
        val active = c.db.topics().active()
        val now = System.currentTimeMillis()

        if (active.isEmpty()) {
            entry?.let { c.db.rounds().upsert(it.copy(note = "Kein aktives Thema")) }
            if (kind == RoundKind.Regular) c.scheduler.scheduleNext()
            return Result.success()
        }

        val settings = c.settings.current()
        if (kind == RoundKind.Regular && !RoundPlanner.isInsideWindow(Instant.ofEpochMilli(now), ZoneId.systemDefault(), settings.windows)) {
            entry?.let { c.db.rounds().upsert(it.copy(note = "Zu spät, außerhalb des Fensters; neu geplant")) }
            c.scheduler.scheduleNext()
            return Result.success()
        }

        val selection = RoundSelection.pick(active.map { it.candidate() }, LocalDate.now(), probe = kind == RoundKind.Probe)
        val byId = active.associateBy { it.issueId }
        selection.updates.forEach { u ->
            byId[u.id]?.let { c.db.topics().upsert(it.copy(inRound = u.inRound, unhandledRounds = u.unhandledRounds)) }
        }
        if (selection.shown.isEmpty()) {
            val note = if (selection.newlyStuck.isNotEmpty()) "Liegen geblieben, nicht erneut gezeigt" else "Nichts fällig; neu geplant"
            entry?.let { c.db.rounds().upsert(it.copy(shownAt = null, note = note)) }
            if (kind == RoundKind.Regular) c.scheduler.scheduleNext()
            return Result.success()
        }
        val shown = selection.shown.mapNotNull { c.db.topics().get(it) }
        Notifications.showRound(applicationContext, shown, probe = kind == RoundKind.Probe, name = settings.bearName)
        entry?.let { c.db.rounds().upsert(it.copy(shownAt = now, note = if (shown.size > 1) "${shown.size} Themen" else it.note)) }
        if (kind == RoundKind.Regular) c.scheduler.scheduleNext()
        return Result.success()
    }

    companion object {
        const val KEY_LOG = "log_id"
        const val KEY_KIND = "kind"
        const val KEY_FALLBACK = "fallback"
    }
}

/**
 * Sends changes made in Bear to Linear: title, Bear block and rhythm label. It reads
 * the issue first and only writes what differs, so repeating it is harmless.
 */
class EditSyncWorker(context: Context, params: WorkerParameters) : CoroutineWorker(context, params) {
    override suspend fun doWork(): Result {
        val c = (applicationContext as BearApp).container
        val id = inputData.getString(KEY_ID) ?: return Result.failure()
        val key = c.settings.apiKey() ?: return Result.success() // sent later, after connecting
        repeat(3) {
            val edit = c.db.edits().get(id) ?: return Result.success()
            val thought = c.db.thoughts().get(id)
            // Not in Linear yet: SendThoughtWorker starts this worker again once the issue exists.
            if (thought != null && thought.state != ThoughtState.InLinear) return Result.success()
            try {
                val issue = c.linear.issue(key, id)
                if (issue == null) {
                    c.db.edits().setError(id, "In Linear nicht gefunden")
                    return Result.failure()
                }
                edit.title?.let { if (it != issue.title) c.linear.updateTitle(key, id, it) }
                val topic = c.db.topics().get(id)
                var description = issue.description
                if (edit.block && topic != null) {
                    val remote = BearBlock.find(issue.description)?.parsed?.block
                    // Only the known fields come from Bear; lines it does not understand stay as they are.
                    val local = (remote ?: BearBlock()).copy(sentences = topic.sentences, step = topic.step, interval = topic.override())
                    if (local != remote) {
                        description = BearBlock.writeInto(issue.description, local)
                        c.linear.updateDescription(key, id, description)
                    }
                }
                edit.rhythmLabel?.let { name ->
                    val target = c.linear.ensureBearLabel(key, name).children.getValue(name.lowercase())
                    val others = issue.labels.filter { it.parentName.equals(RhythmChoice.LINEAR_GROUP, ignoreCase = true) && it.id != target }.map { it.id }
                    val has = issue.labels.any { it.id == target }
                    // Remove the old child and add the new one in one call; Linear allows one per group.
                    if (!has || others.isNotEmpty()) c.linear.updateLabels(key, id, added = if (has) emptyList() else listOf(target), removed = others)
                }
                if (topic != null) c.db.topics().setDescription(id, description, System.currentTimeMillis())
                if (c.db.edits().done(id, edit.version) == 1) return Result.success()
                // Something new came in while sending: go round once more.
            } catch (e: LinearException) {
                c.db.edits().setError(id, e.message)
                return if (e.retryable) Result.retry() else Result.failure()
            }
        }
        return Result.success()
    }

    companion object { const val KEY_ID = "issue_id" }
}

private fun TopicEntity.candidate() = RoundCandidate(issueId, inRound, unhandledRounds, LocalDate.ofEpochDay(nextDueEpochDay))

package app.kiumu.bear.data.linear

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import app.kiumu.bear.domain.RhythmChoice
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.JsonNull
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlinx.serialization.json.put
import kotlinx.serialization.json.putJsonObject
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.RequestBody.Companion.toRequestBody
import java.io.IOException
import java.util.concurrent.TimeUnit

class LinearException(message: String, val retryable: Boolean) : Exception(message)

data class LinearLabel(val id: String, val name: String, val parentName: String?)

data class LinearIssue(
    val id: String,
    val identifier: String,
    val title: String,
    val description: String?,
    val url: String,
    val stateType: String,
    val updatedAt: String,
    val labels: List<LinearLabel> = emptyList(),
) {
    /** Done, canceled or marked as duplicate in Linear. */
    val ended: Boolean get() = stateType == "completed" || stateType == "canceled" || stateType == "duplicate"

    /** The child label of the group „Bear“, if the issue has one. */
    val bearLabel: LinearLabel? get() = labels.firstOrNull { it.parentName.equals(RhythmChoice.LINEAR_GROUP, ignoreCase = true) }
}

data class InboxTarget(val teamId: String, val triageStateId: String)

data class CreatedIssue(val identifier: String, val url: String)

/** The workspace label group „Bear“ and its child labels by lower-case name. */
data class BearLabels(val groupId: String, val children: Map<String, String>)

/**
 * Minimal GraphQL client for Linear with a personal API key.
 * HTTP 200 alone is not success: GraphQL errors are checked on every call.
 */
class LinearClient(private val http: OkHttpClient = defaultHttp()) {

    suspend fun viewerName(apiKey: String): String {
        val data = call(apiKey, "query { viewer { name } }", buildJsonObject { })
        return data["viewer"]!!.jsonObject["name"]!!.jsonPrimitive.content
    }

    /** Finds INBOX (key BOX or name INBOX) and its triage state. */
    suspend fun inboxTarget(apiKey: String): InboxTarget {
        val q = "query { teams(first: 50) { nodes { id key name states { nodes { id type } } } } }"
        val nodes = call(apiKey, q, buildJsonObject { })["teams"]!!.jsonObject["nodes"]!!.jsonArray
        val team = nodes.map { it.jsonObject }.firstOrNull {
            it.str("key") == "BOX" || it.str("name").equals("INBOX", ignoreCase = true)
        } ?: throw LinearException("Team INBOX nicht gefunden", retryable = false)
        val states = team["states"]!!.jsonObject["nodes"]!!.jsonArray.map { it.jsonObject }
        val triage = states.firstOrNull { it.str("type") == "triage" }
            ?: states.firstOrNull { it.str("type") == "backlog" }
            ?: throw LinearException("Kein Triage-Status in INBOX", retryable = false)
        return InboxTarget(team.str("id")!!, triage.str("id")!!)
    }

    /** Creates an issue with our own UUID, so a retry can check whether it already exists. */
    suspend fun createIssue(apiKey: String, id: String, target: InboxTarget, title: String, description: String?): CreatedIssue {
        val q = "mutation(\$input: IssueCreateInput!) { issueCreate(input: \$input) { success issue { identifier url } } }"
        val vars = buildJsonObject {
            putJsonObject("input") {
                put("id", id)
                put("teamId", target.teamId)
                put("stateId", target.triageStateId)
                put("title", title)
                if (description != null) put("description", description)
            }
        }
        val result = call(apiKey, q, vars)["issueCreate"]!!.jsonObject
        if (result["success"]?.jsonPrimitive?.content != "true") throw LinearException("issueCreate ohne Erfolg", retryable = true)
        val issue = (result["issue"] as? JsonObject) ?: throw LinearException("issueCreate ohne Issue", retryable = true)
        return CreatedIssue(issue.str("identifier")!!, issue.str("url")!!)
    }

    /** Replaces the description. Callers only do this when the Bear block really changed. */
    suspend fun updateDescription(apiKey: String, issueId: String, description: String) =
        update(apiKey, issueId, buildJsonObject { put("description", description) })

    suspend fun updateTitle(apiKey: String, issueId: String, title: String) =
        update(apiKey, issueId, buildJsonObject { put("title", title) })

    /** Adds and removes labels in one call and leaves all other labels of the issue alone. */
    suspend fun updateLabels(apiKey: String, issueId: String, added: List<String>, removed: List<String>) =
        update(apiKey, issueId, buildJsonObject {
            put("addedLabelIds", JsonArray(added.map { JsonPrimitive(it) }))
            put("removedLabelIds", JsonArray(removed.map { JsonPrimitive(it) }))
        })

    private suspend fun update(apiKey: String, issueId: String, input: JsonObject) {
        val q = "mutation(\$id: String!, \$input: IssueUpdateInput!) { issueUpdate(id: \$id, input: \$input) { success } }"
        val vars = buildJsonObject {
            put("id", issueId)
            put("input", input)
        }
        val result = call(apiKey, q, vars)["issueUpdate"]!!.jsonObject
        if (result["success"]?.jsonPrimitive?.content != "true") throw LinearException("issueUpdate ohne Erfolg", retryable = true)
    }

    /** Loads an issue by UUID or by identifier such as LIFE-29. Null if it does not exist. */
    suspend fun issue(apiKey: String, idOrIdentifier: String): LinearIssue? {
        val q = "query(\$id: String!) { issue(id: \$id) { $ISSUE_FIELDS } }"
        val data = try {
            call(apiKey, q, buildJsonObject { put("id", idOrIdentifier) })
        } catch (e: LinearException) {
            if (!e.retryable && e.message.orEmpty().contains("not found", ignoreCase = true)) return null
            throw e
        }
        val node = data["issue"]
        if (node == null || node is JsonNull) return null
        return node.jsonObject.toIssue()
    }

    /**
     * Loads several issues by UUID. Archived or deleted ones are simply missing from
     * the result. Labels are capped at 10 per issue to stay below Linear's query
     * complexity limit.
     */
    suspend fun issues(apiKey: String, ids: List<String>): List<LinearIssue> = ids.chunked(50).flatMap { chunk ->
        val q = "query(\$ids: [ID!]) { issues(filter: { id: { in: \$ids } }, first: 50) { nodes { $ISSUE_FIELDS } } }"
        val vars = buildJsonObject { put("ids", JsonArray(chunk.map { JsonPrimitive(it) })) }
        call(apiKey, q, vars)["issues"]!!.jsonObject["nodes"]!!.jsonArray.map { it.jsonObject.toIssue() }
    }

    /**
     * The open issues that changed last, newest first: what the user is likely busy with.
     * Done, canceled and duplicate issues are left out.
     */
    suspend fun recentIssues(apiKey: String, count: Int): List<LinearIssue> {
        val q = "query(\$first: Int!) { issues(first: \$first, orderBy: updatedAt, " +
            "filter: { state: { type: { nin: [\"completed\", \"canceled\", \"duplicate\"] } } }) { nodes { $ISSUE_FIELDS } } }"
        val vars = buildJsonObject { put("first", count) }
        return call(apiKey, q, vars)["issues"]!!.jsonObject["nodes"]!!.jsonArray.map { it.jsonObject.toIssue() }
    }

    /**
     * Finds the workspace label group „Bear“ and makes sure it has a child label with
     * [childName]. Creates what is missing. Fails if the key may not manage labels.
     */
    suspend fun ensureBearLabel(apiKey: String, childName: String): BearLabels {
        val q = "query { issueLabels(filter: { name: { eqIgnoreCase: \"${RhythmChoice.LINEAR_GROUP}\" }, isGroup: { eq: true }, team: { null: true } }, first: 10) " +
            "{ nodes { id children { nodes { id name } } } } }"
        val group = call(apiKey, q, buildJsonObject { })["issueLabels"]!!.jsonObject["nodes"]!!.jsonArray.firstOrNull()?.jsonObject
        val groupId = group?.str("id") ?: createLabel(apiKey, buildJsonObject {
            put("name", RhythmChoice.LINEAR_GROUP)
            put("isGroup", true)
            put("color", LABEL_COLOR)
        })
        val children = group?.get("children")?.jsonObject?.get("nodes")?.jsonArray.orEmpty()
            .associate { it.jsonObject.str("name")!!.lowercase() to it.jsonObject.str("id")!! }
            .toMutableMap()
        if (childName.lowercase() !in children) {
            children[childName.lowercase()] = createLabel(apiKey, buildJsonObject {
                put("name", childName)
                put("parentId", groupId)
                put("color", LABEL_COLOR)
            })
        }
        return BearLabels(groupId, children)
    }

    private suspend fun createLabel(apiKey: String, input: JsonObject): String {
        val q = "mutation(\$input: IssueLabelCreateInput!) { issueLabelCreate(input: \$input) { success issueLabel { id } } }"
        val result = call(apiKey, q, buildJsonObject { put("input", input) })["issueLabelCreate"]!!.jsonObject
        if (result["success"]?.jsonPrimitive?.content != "true") throw LinearException("Label konnte nicht angelegt werden", retryable = false)
        return result["issueLabel"]!!.jsonObject.str("id")!!
    }

    private fun JsonObject.toIssue() = LinearIssue(
        id = str("id")!!,
        identifier = str("identifier")!!,
        title = str("title")!!,
        description = str("description"),
        url = str("url")!!,
        stateType = this["state"]!!.jsonObject.str("type")!!,
        updatedAt = str("updatedAt")!!,
        labels = (this["labels"] as? JsonObject)?.get("nodes")?.jsonArray.orEmpty().map { l ->
            val o = l.jsonObject
            LinearLabel(o.str("id")!!, o.str("name")!!, (o["parent"] as? JsonObject)?.str("name"))
        },
    )

    private suspend fun call(apiKey: String, query: String, variables: JsonObject): JsonObject = withContext(Dispatchers.IO) {
        val body = buildJsonObject {
            put("query", query)
            put("variables", variables)
        }.toString().toRequestBody("application/json".toMediaType())
        val request = Request.Builder()
            .url("https://api.linear.app/graphql")
            .header("Authorization", apiKey)
            .post(body)
            .build()
        val response = try {
            http.newCall(request).execute()
        } catch (e: IOException) {
            throw LinearException("Keine Verbindung: ${e.message}", retryable = true)
        }
        response.use { r ->
            val text = r.body.string()
            if (r.code == 401 || r.code == 403) throw LinearException("Schlüssel ungültig oder ohne Rechte", retryable = false)
            if (r.code == 429 || r.code >= 500) throw LinearException("Linear antwortet gerade nicht (${r.code})", retryable = true)
            val json = runCatching { Json.parseToJsonElement(text).jsonObject }.getOrElse {
                throw LinearException("Unerwartete Antwort (${r.code})", retryable = true)
            }
            val errors = json["errors"]
            if (errors != null && errors !is JsonNull) {
                val msg = errors.jsonArray.firstOrNull()?.jsonObject?.str("message") ?: "GraphQL-Fehler"
                throw LinearException(msg, retryable = false)
            }
            json["data"]?.jsonObject ?: throw LinearException("Antwort ohne Daten", retryable = true)
        }
    }

    companion object {
        private const val ISSUE_FIELDS =
            "id identifier title description url updatedAt state { type } labels(first: 10) { nodes { id name parent { id name } } }"
        private const val LABEL_COLOR = "#A5431D"

        fun defaultHttp(): OkHttpClient = OkHttpClient.Builder()
            .connectTimeout(15, TimeUnit.SECONDS)
            .readTimeout(20, TimeUnit.SECONDS)
            .build()
    }
}

private fun JsonObject.str(key: String): String? =
    (this[key] as? JsonElement)?.takeIf { it !is JsonNull }?.jsonPrimitive?.content

package app.kiumu.bear.domain

import java.time.LocalDateTime
import kotlin.random.Random

/**
 * The small widget shows one entry at random and changes it every four hours, at
 * 0, 4, 8, 12, 16 and 20 o'clock. Fixed times make the change easy to check. The
 * entry stays for its slot even if other entries come or go; only if it disappears
 * does another one take its place.
 */
object WidgetPick {
    const val HOURS = 4

    /** A number for each four-hour slot, counted in local time. */
    fun slot(now: LocalDateTime): Long = now.toLocalDate().toEpochDay() * (24 / HOURS) + now.hour / HOURS

    /** When the next slot starts, in local time. */
    fun nextChange(now: LocalDateTime): LocalDateTime =
        now.toLocalDate().atTime(now.hour / HOURS * HOURS, 0).plusHours(HOURS.toLong())

    /**
     * Keeps [current] while its slot lasts and it still exists. Otherwise picks another
     * entry at random; the same one twice in a row only if there is no other.
     */
    fun pick(ids: List<String>, current: String?, currentSlot: Long?, slot: Long, random: Random = Random.Default): String? {
        if (current != null && currentSlot == slot && current in ids) return current
        if (ids.isEmpty()) return null
        return ids.filter { it != current }.ifEmpty { ids }.random(random)
    }
}

