import java.time.LocalDate

class RoundSelectionTest {
    private val today = LocalDate.of(2026, 9, 26)
    private fun c(id: String, due: Int = 0, inRound: Boolean = false, unhandled: Int = 0) =
        RoundCandidate(id, inRound, unhandled, today.plusDays(due.toLong()))

    @Test fun bringsAtMostThreeMostOverdueFirst() {
        val r = RoundSelection.pick(listOf(c("a", 0), c("b", -3), c("c", -1), c("d", -2), c("e", 2)), today)
        assertEquals(listOf("b", "d", "c"), r.shown)
        assertTrue(r.updates.all { it.inRound && it.unhandledRounds == 0 })
    }

    @Test fun waitingTopicsComeFirstAndCountAnUnansweredRound() {
        val r = RoundSelection.pick(listOf(c("new", -5), c("old", 0, inRound = true, unhandled = 1)), today, max = 1)
        assertEquals(listOf("old"), r.shown)
        assertEquals(RoundSelection.Update("old", inRound = true, unhandledRounds = 2), r.updates.single())
    }

    @Test fun afterThreeUnansweredRoundsATopicIsNoLongerShown() {
        val r = RoundSelection.pick(listOf(c("old", 0, inRound = true, unhandled = 2), c("new", 0)), today)
        assertEquals(listOf("new"), r.shown)
        assertEquals(listOf("old"), r.newlyStuck)
        assertEquals(RoundSelection.Update("old", inRound = false, unhandledRounds = 3), r.updates.first { it.id == "old" })
    }

    @Test fun aStuckTopicStaysOutUntilItIsAnswered() {
        val r = RoundSelection.pick(listOf(c("stuck", -10, unhandled = 3)), today)
        assertTrue(r.shown.isEmpty())
        assertNull(RoundSelection.nextDueDay(listOf(c("stuck", -10, unhandled = 3)), today))
    }

    @Test fun aProbeRoundAlwaysBringsSomethingAndCountsNothing() {
        val r = RoundSelection.pick(listOf(c("later", 5), c("waiting", 0, inRound = true, unhandled = 1)), today, probe = true)
        assertEquals(listOf("waiting"), r.shown)
        assertEquals(1, r.updates.single { it.id == "waiting" }.unhandledRounds)
        val nothingDue = RoundSelection.pick(listOf(c("later", 5)), today, probe = true)
        assertEquals(listOf("later"), nothingDue.shown)
    }

    @Test fun nextRoundIsTomorrowForWaitingTopicsOtherwiseTheEarliestDueDay() {
        assertEquals(today.plusDays(1), RoundSelection.nextDueDay(listOf(c("w", 0, inRound = true), c("x", 4)), today))
        assertEquals(today.plusDays(4), RoundSelection.nextDueDay(listOf(c("x", 4), c("y", 9)), today))
        assertEquals(today, RoundSelection.nextDueDay(listOf(c("overdue", -3)), today))
    }
}

class RhythmChoiceTest {
    private val today = LocalDate.of(2026, 9, 26)
    private val topic = TopicEntity(
        issueId = "i", identifier = "BOX-1", title = "T", url = "", sentences = emptyList(), step = null,
        intervalFrom = null, intervalTo = null, rhythm = Rhythm.Normal.name, intervalFactor = 1.4,
        nextDueEpochDay = today.plusDays(5).toEpochDay(), inRound = false, unhandledRounds = 0,
        sentenceIndex = 0, sentenceUses = 0, linearStateType = "backlog", status = TopicStatus.Active, lastSyncedAt = 0,
    )

    @Test fun readsTheLinearLabelWhateverTheCase() {
        assertEquals(RhythmChoice.Merken, RhythmChoice.fromLinearLabel(" Nur merken "))
        assertEquals(RhythmChoice.Oft, RhythmChoice.fromLinearLabel("OFT"))
        assertNull(RhythmChoice.fromLinearLabel("wichtig"))
    }

    @Test fun aNewRhythmStartsFreshInsideItsRange() {
        val t = topic.withChoice(RhythmChoice.Selten, today)
        assertEquals(Rhythm.Selten.name, t.rhythm)
        assertEquals(1.0, t.intervalFactor, 0.0)
        assertTrue(t.nextDueEpochDay - today.toEpochDay() in 14L..28L)
    }

    @Test fun theSameRhythmKeepsFactorAndDueDay() {
        val t = topic.withChoice(RhythmChoice.Normal, today)
        assertEquals(topic, t)
    }

    @Test fun nurMerkenLeavesTheRoundsAndComesBack() {
        val kept = topic.copy(inRound = true).withChoice(RhythmChoice.Merken, today)
        assertEquals(TopicStatus.Remembered, kept.status)
        assertEquals(RhythmChoice.Merken, kept.choice())
        assertEquals(TopicStatus.Active, kept.withChoice(RhythmChoice.Oft, today).status)
    }

    @Test fun aChangeFromLinearDoesNotResumeAPausedTopic() {
        val paused = topic.copy(status = TopicStatus.Paused)
        assertEquals(TopicStatus.Paused, paused.withChoice(RhythmChoice.Oft, today, resume = false).status)
        assertEquals(TopicStatus.Active, paused.withChoice(RhythmChoice.Oft, today).status)
    }
}

package app.kiumu.bear.domain

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotEquals
import org.junit.Assert.assertNull
import org.junit.Test
import java.time.LocalDateTime
import kotlin.random.Random

class WidgetPickTest {
    private val ids = listOf("a", "b", "c", "d")

    @Test fun slotsStartEveryFourHours() {
        val day = LocalDateTime.of(2026, 9, 27, 0, 0)
        assertEquals(WidgetPick.slot(day), WidgetPick.slot(day.withHour(3).withMinute(59)))
        assertEquals(WidgetPick.slot(day) + 1, WidgetPick.slot(day.withHour(4)))
        assertEquals(WidgetPick.slot(day) + 5, WidgetPick.slot(day.withHour(23).withMinute(59)))
        assertEquals(WidgetPick.slot(day) + 6, WidgetPick.slot(day.plusDays(1)))
    }

    @Test fun nextChangeIsTheNextFourHourMark() {
        assertEquals(LocalDateTime.of(2026, 9, 27, 16, 0), WidgetPick.nextChange(LocalDateTime.of(2026, 9, 27, 12, 0)))
        assertEquals(LocalDateTime.of(2026, 9, 27, 16, 0), WidgetPick.nextChange(LocalDateTime.of(2026, 9, 27, 15, 59)))
        assertEquals(LocalDateTime.of(2026, 9, 28, 0, 0), WidgetPick.nextChange(LocalDateTime.of(2026, 9, 27, 21, 30)))
    }

    @Test fun keepsTheEntryWhileTheSlotLasts() {
        repeat(20) { assertEquals("b", WidgetPick.pick(ids, "b", 7, 7, Random(it))) }
    }

    @Test fun aNewSlotBringsAnotherEntry() {
        repeat(50) { assertNotEquals("b", WidgetPick.pick(ids, "b", 7, 8, Random(it))) }
    }

    @Test fun everyEntryCanComeUp() {
        val seen = (0 until 200).mapNotNull { WidgetPick.pick(ids, null, null, 1, Random(it)) }.toSet()
        assertEquals(ids.toSet(), seen)
    }

    @Test fun aRemovedEntryIsReplacedInTheSameSlot() {
        repeat(20) { assertNotEquals("b", WidgetPick.pick(listOf("a", "c"), "b", 7, 7, Random(it))) }
    }

    @Test fun aSingleEntryStaysAndNoEntryGivesNothing() {
        assertEquals("a", WidgetPick.pick(listOf("a"), "a", 7, 8))
        assertNull(WidgetPick.pick(emptyList(), "a", 7, 8))
    }
}

