package app.kiumu.bear.alarm

import android.app.AlarmManager
import android.app.PendingIntent
import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import androidx.work.Constraints
import androidx.work.ExistingWorkPolicy
import androidx.work.NetworkType
import androidx.work.OneTimeWorkRequestBuilder
import androidx.work.OutOfQuotaPolicy
import androidx.work.WorkManager
import androidx.work.workDataOf
import app.kiumu.bear.BearApp
import app.kiumu.bear.data.db.BearDatabase
import app.kiumu.bear.data.db.RoundKind
import app.kiumu.bear.data.db.RoundLogEntity
import app.kiumu.bear.data.settings.SettingsStore
import app.kiumu.bear.domain.RoundCandidate
import app.kiumu.bear.domain.RoundPlanner
import app.kiumu.bear.domain.RoundSelection
import app.kiumu.bear.widget.WidgetUpdates
import app.kiumu.bear.work.RoundWorker
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.launch
import java.time.LocalDate
import java.time.ZonedDateTime
import java.util.concurrent.TimeUnit

/**
 * Plans only the next round and keeps it in the database. Every trigger (app start,
 * reboot, update, time change, after a round, after a change) calls the same code.
 */
class RoundScheduler(
    private val context: Context,
    private val db: BearDatabase,
    private val settings: SettingsStore,
) {
    private val alarms = context.getSystemService(AlarmManager::class.java)

    suspend fun scheduleNext(now: ZonedDateTime = ZonedDateTime.now()) {
        // Unhandled topics come back in the next window; otherwise the earliest due day counts.
        val candidates = db.topics().active().map { RoundCandidate(it.issueId, it.inRound, it.unhandledRounds, LocalDate.ofEpochDay(it.nextDueEpochDay)) }
        val due = RoundSelection.nextDueDay(candidates, now.toLocalDate())
        if (due == null) {
            cancel(); settings.setNextRoundAt(null); return
        }
        val at = RoundPlanner.nextRoundAt(now, due, settings.current().windows).toInstant().toEpochMilli()
        // A round that has not come yet is moved, not added again. Otherwise the log would
        // later show the old plan as "nicht gekommen".
        val pending = db.rounds().pendingRegular(now.toInstant().toEpochMilli())
        val logId = pending?.let { db.rounds().upsert(it.copy(plannedAt = at)); it.id }
            ?: db.rounds().insert(RoundLogEntity(kind = RoundKind.Regular, plannedAt = at))
        settings.setNextRoundAt(at)
        set(at, logId, RoundKind.Regular)
    }

    /** A test round, by default one minute from now. It does not change the topic's rhythm. Returns its log id. */
    suspend fun scheduleProbe(delayMs: Long = 60_000): Long {
        val at = System.currentTimeMillis() + delayMs
        val logId = db.rounds().insert(RoundLogEntity(kind = RoundKind.Probe, plannedAt = at, note = "Probe-Runde"))
        set(at, logId, RoundKind.Probe)
        return logId
    }

    /** Stops a probe round that has not been shown yet: its alarm and any work waiting for network. */
    suspend fun cancelProbe(logId: Long) {
        val entry = db.rounds().byId(logId) ?: return
        if (entry.shownAt != null) return
        alarms.cancel(pending(logId, RoundKind.Probe))
        WorkManager.getInstance(context).apply {
            cancelUniqueWork("round-$logId")
            cancelUniqueWork("round-$logId-fallback")
        }
        db.rounds().upsert(entry.copy(note = "In der App angesehen"))
    }

    /** Re-registers the stored alarm, for example after a reboot. Missed rounds are re-planned. */
    suspend fun restore() {
        val at = settings.current().nextRoundAt
        if (at == null || at < System.currentTimeMillis()) scheduleNext()
        else set(at, db.rounds().pendingRegular(System.currentTimeMillis())?.id ?: -1, RoundKind.Regular)
    }

    private fun set(at: Long, logId: Long, kind: RoundKind) {
        val pi = pending(logId, kind)
        if (alarms.canScheduleExactAlarms()) {
            alarms.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, at, pi)
        } else {
            alarms.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, at, pi)
        }
    }

    private fun cancel() = alarms.cancel(pending(-1, RoundKind.Regular))

    private fun pending(logId: Long, kind: RoundKind): PendingIntent {
        val intent = Intent(context, RoundAlarmReceiver::class.java)
            .putExtra(RoundWorker.KEY_LOG, logId)
            .putExtra(RoundWorker.KEY_KIND, kind.name)
        val requestCode = if (kind == RoundKind.Probe) 2 else 1
        return PendingIntent.getBroadcast(context, requestCode, intent, PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT)
    }
}

/** Receives the alarm, logs the actual time and hands over to WorkManager. */
class RoundAlarmReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        val logId = intent.getLongExtra(RoundWorker.KEY_LOG, -1)
        val kind = intent.getStringExtra(RoundWorker.KEY_KIND) ?: RoundKind.Regular.name
        val pending = goAsync()
        val c = (context.applicationContext as BearApp).container
        CoroutineScope(SupervisorJob() + Dispatchers.IO).launch {
            try {
                c.db.rounds().byId(logId)?.let { c.db.rounds().upsert(it.copy(firedAt = System.currentTimeMillis())) }
                val wm = WorkManager.getInstance(context)
                val data = workDataOf(RoundWorker.KEY_LOG to logId, RoundWorker.KEY_KIND to kind)
                val online = OneTimeWorkRequestBuilder<RoundWorker>()
                    .setInputData(data)
                    .setConstraints(Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build())
                    .setExpedited(OutOfQuotaPolicy.RUN_AS_NON_EXPEDITED_WORK_REQUEST)
                    .build()
                val fallback = OneTimeWorkRequestBuilder<RoundWorker>()
                    .setInputData(workDataOf(RoundWorker.KEY_LOG to logId, RoundWorker.KEY_KIND to kind, RoundWorker.KEY_FALLBACK to true))
                    .setInitialDelay(3, TimeUnit.MINUTES)
                    .build()
                wm.enqueueUniqueWork("round-$logId", ExistingWorkPolicy.KEEP, online)
                wm.enqueueUniqueWork("round-$logId-fallback", ExistingWorkPolicy.KEEP, fallback)
            } finally {
                pending.finish()
            }
        }
    }
}

/** Reboot, app update and time changes all lead to the same re-planning. */
class RescheduleReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        val pending = goAsync()
        val c = (context.applicationContext as BearApp).container
        CoroutineScope(SupervisorJob() + Dispatchers.IO).launch {
            try {
                if (intent.action == Intent.ACTION_TIMEZONE_CHANGED || intent.action == Intent.ACTION_TIME_CHANGED) c.scheduler.scheduleNext()
                else c.scheduler.restore()
                c.thoughts.resendPending()
                c.edits.enqueueAll()
                // A widget problem must not stop the rest of the re-planning.
                runCatching { WidgetUpdates.refreshAndPlan(context) }
            } finally {
                pending.finish()
            }
        }
    }
}

/** The „Später“ action on the notification: the waiting topics come back tomorrow. */
class LaterReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        val pending = goAsync()
        val c = (context.applicationContext as BearApp).container
        CoroutineScope(SupervisorJob() + Dispatchers.IO).launch {
            try {
                c.topics.laterAll()
                c.scheduler.scheduleNext()
                app.kiumu.bear.notify.Notifications.cancelRound(context)
            } finally {
                pending.finish()
            }
        }
    }
}

