/** One entry as the widgets show it. No dates in it, so a new day alone does not redraw them. */
data class WidgetEntry(
    val id: String,
    val title: String,
    val step: String?,
    val isTopic: Boolean,
    /** „wartet auf dich“ or „liegen geblieben“: the entry asks for attention. */
    val note: String? = null,
)

data class WidgetEntries(val topics: List<WidgetEntry> = emptyList(), val thoughts: List<WidgetEntry> = emptyList()) {
    val all: List<WidgetEntry> get() = topics + thoughts
}

fun widgetEntries(topics: List<TopicEntity>, thoughts: List<ThoughtEntity>): WidgetEntries {
    val (t, th) = entriesInOrder(topics, thoughts)
    return WidgetEntries(
        topics = t.map {
            val note = when {
                it.inRound -> "wartet auf dich"
                it.stuck -> "liegen geblieben"
                else -> null
            }
            WidgetEntry(it.issueId, it.title, it.step, isTopic = true, note = note)
        },
        thoughts = th.map { WidgetEntry(it.id, ThoughtText.split(it.text).first, null, isTopic = false) },
    )
}

fun BearDatabase.widgetEntries(): Flow<WidgetEntries> =
    combine(topics().observeAll(), thoughts().observeAll(), ::widgetEntries).distinctUntilChanged()

private val Context.widgetStore by preferencesDataStore(name = "widgets")

/** Which entry each small widget shows, and for which four-hour slot. */
class PickStore(private val context: Context) {
    private fun idKey(widget: Int) = stringPreferencesKey("pick_$widget")
    private fun slotKey(widget: Int) = longPreferencesKey("pick_slot_$widget")

    fun pick(widget: Int): Flow<String?> = context.widgetStore.data.map { it[idKey(widget)] }.distinctUntilChanged()

    /** Keeps the entry for its slot, or picks a new one. Returns the entry to show. */
    suspend fun choose(widget: Int, ids: List<String>, now: LocalDateTime = LocalDateTime.now()): String? {
        var chosen: String? = null
        context.widgetStore.edit { p ->
            val slot = WidgetPick.slot(now)
            chosen = WidgetPick.pick(ids, p[idKey(widget)], p[slotKey(widget)], slot)
            chosen?.let { p[idKey(widget)] = it } ?: p.remove(idKey(widget))
            p[slotKey(widget)] = slot
        }
        return chosen
    }

    suspend fun forget(widgets: IntArray) = context.widgetStore.edit { p ->
        widgets.forEach { p.remove(idKey(it)); p.remove(slotKey(it)) }
    }
}

/**
 * Keeps both widgets in step with the database and gives the small one a new entry
 * every four hours. Only this app writes the database, so watching it while the
 * process runs is enough.
 */
object WidgetUpdates {
    private val watching = AtomicBoolean(false)
    val scope = CoroutineScope(SupervisorJob() + Dispatchers.Default)

    fun anyPlaced(context: Context): Boolean {
        val manager = AppWidgetManager.getInstance(context)
        return listOf(EntriesWidgetReceiver::class.java, PickWidgetReceiver::class.java)
            .any { manager.getAppWidgetIds(ComponentName(context, it)).isNotEmpty() }
    }

    /** Starts watching, once per process. Called at app start with widgets placed, and whenever a widget is drawn. */
    @OptIn(FlowPreview::class)
    fun watch(context: Context) {
        if (!watching.compareAndSet(false, true)) return
        val app = context.applicationContext
        val db = (app as BearApp).container.db
        scope.launch {
            // A sync writes topic after topic; the widgets are redrawn once it is done.
            db.widgetEntries().debounce(500).collectLatest { runCatching { refresh(app, it) } }
        }
    }

    /** Redraws both widgets. The small one keeps its entry unless it is gone or its four hours are up. */
    suspend fun refresh(context: Context, entries: WidgetEntries) {
        val manager = GlanceAppWidgetManager(context)
        val picks = PickStore(context)
        val ids = entries.all.map { it.id }
        manager.getGlanceIds(PickWidget::class.java).forEach { id ->
            picks.choose(manager.getAppWidgetId(id), ids)
            PickWidget().update(context, id)
        }
        EntriesWidget().updateAll(context)
    }

    /** At each change, after a reboot, an update or a time change. */
    suspend fun refreshAndPlan(context: Context) {
        val db = (context.applicationContext as BearApp).container.db
        refresh(context, db.widgetEntries().first())
        planNextChange(context)
    }

    fun planNextChange(context: Context, now: LocalDateTime = LocalDateTime.now()) {
        val alarms = context.getSystemService(AlarmManager::class.java)
        val placed = AppWidgetManager.getInstance(context).getAppWidgetIds(ComponentName(context, PickWidgetReceiver::class.java))
        if (placed.isEmpty()) {
            alarms.cancel(changeIntent(context)); return
        }
        val at = WidgetPick.nextChange(now).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli()
        // No wake-up: a widget nobody looks at can wait until the screen is on again.
        alarms.setWindow(AlarmManager.RTC, at, 10 * 60_000L, changeIntent(context))
    }

    fun cancelChange(context: Context) = context.getSystemService(AlarmManager::class.java).cancel(changeIntent(context))

    private fun changeIntent(context: Context): PendingIntent = PendingIntent.getBroadcast(
        context, 0, Intent(context, WidgetChangeReceiver::class.java),
        PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT,
    )
}

/** Every four hours: a new entry in the small widget. */
class WidgetChangeReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        val pending = goAsync()
        WidgetUpdates.scope.launch {
            try {
                runCatching { WidgetUpdates.refreshAndPlan(context) }
            } finally {
                pending.finish()
            }
        }
    }
}
